$_MODULE['<{layerslider}prestashop>_113aa97ee6c663a84fd3092604794b7d'] = 'Se abiliti questa opzione, le transizioni dei livelli non inizieranno a riprodursi finché lo slideshow è in pausa.'; // If you enable this option, layer transitions will not start playing as long the slideshow is in a paused state.
