$_MODULE['<{layerslider}prestashop>_cd88ce600576fcc630878b5e374835a5'] = 'Nessuna azione'; // Do nothing
$_MODULE['<{layerslider}prestashop>_f30a5a0a150bc99b997ffb468904b06e'] = 'Metti in pausa lo slideshow'; // Pause slideshow
$_MODULE['<{layerslider}prestashop>_7252683ddf448008ac21fb654fe3ddf1'] = 'Metti in pausa slideshow e transizioni dei livelli'; // Pause slideshow and layer transitions
$_MODULE['<{layerslider}prestashop>_a53243d823bbc7edc8bbff9552664813'] = 'Metti in pausa slideshow e transizioni dei livelli, inclusi i loop'; // Pause slideshow and layer transitions, including loops
$_MODULE['<{layerslider}prestashop>_f0f6443b0e7af244931c23a6846b5e0c'] = 'Decidi cosa deve accadere quando sposti il cursore del mouse sopra lo slider.'; // Decide what should happen when you move your mouse cursor over the slider.
