$_MODULE['<{layerslider}prestashop>_1bc04399c429370c3a42ebc85703da44'] = 'Lo slider inizierà con la slide specificata. Puoi anche usare il valore "random".'; // The slider will start with the specified slide. You can also use the value "random".
