$_MODULE['<{layerslider}prestashop>_6a517bb511f7213857b8f8875bd328e1'] = 'Lo slideshow procederà in ordine casuale. Questa funzione non funziona con il loop.'; // Slideshow will proceed in random order. This feature does not work with looping.
