$_MODULE['<{layerslider}prestashop>_349e59be41d9343db58b7808bc28499b'] = 'Puoi inserire CSS personalizzato per cambiare alcune proprietà di stile sull\'elemento contenitore dello slider. CSS più complessi dovrebbero essere applicati con l\'Editor di Stili Personalizzati.'; // You can enter custom CSS to change some style properties on the slider wrapper element. More complex CSS should be applied with the Custom Styles Editor.
$_MODULE['<{layerslider}prestashop>_368d9ac76af05f714092bc808a426bfc'] = 'Colore di sfondo'; // Background color
$_MODULE['<{layerslider}prestashop>_982df53492cb5149371541dcabf1cc3d'] = 'Colore di sfondo globale dello slider. Le slide con sfondo non trasparente copriranno questo. Puoi usare tutti i metodi CSS come valori HEX o RGB(A).'; // Global background color of the slider. Slides with non-transparent background will cover this one. You can use all CSS methods such as HEX or RGB(A) values.
