$_MODULE['<{layerslider}prestashop>_ff9acc881ce27cbef995d5c6074a5e46'] = 'Dimensione dello sfondo globale dello slider. Puoi impostare la dimensione in pixel, percentuali o costanti: auto | cover | contain'; // Global background size of the slider. You can set the size in pixels, percentages, or constants: auto | cover | contain
