$_MODULE['<{layerslider}prestashop>_6312fa38f1807efc7b1bc2e1608dbfda'] = 'Disabilitando questa opzione si nasconderanno i pulsanti di navigazione delle slide o le miniature.'; // Disabling this option will hide slide navigation buttons or thumbnails.
