$_MODULE['<{layerslider}prestashop>_c24735d116a5f3d4f79022bfe8c53c49'] = 'I pulsanti di navigazione delle slide (incluse le miniature) verranno mostrati solo al passaggio del mouse.'; // Slide navigation buttons (including thumbnails) will be shown on mouse hover only.
