$_MODULE['<{layerslider}prestashop>_1d9c34a1e5abf100183b4ad7532c41b7'] = 'Usa il timer a cerchio per indicare l\'avanzamento dello slideshow.'; // Use circle timer to indicate slideshow progression.
$_MODULE['<{layerslider}prestashop>_de71b95202c887194728701b80b29e80'] = 'Mostra timer a barra di scorrimento'; // Show slidebar timer
$_MODULE['<{layerslider}prestashop>_44296e11edf32fa766684b26d7705ebf'] = 'Puoi afferrare la testina di riproduzione del timer a barra di scorrimento e cercare l\'intera slide in tempo reale come un film.'; // You can grab the slidebar timer playhead and seek the whole slide real-time like a movie.
$_MODULE['<{layerslider}prestashop>_3fcedab9558638bde418786a33094642'] = 'Navigazione con miniature'; // Thumbnail navigation
$_MODULE['<{layerslider}prestashop>_b69c76269a74010901e9ee7ed59c22ff'] = 'Usa la navigazione con miniature invece dei pulsanti a pallini delle slide.'; // Use thumbnail navigation instead of slide bullet buttons.
$_MODULE['<{layerslider}prestashop>_b9f5c797ebbf55adccdd8539a65a0241'] = 'Disabilitato'; // Disabled
$_MODULE['<{layerslider}prestashop>_eee0168be69b854c20621fc6f01cc3fc'] = 'Al passaggio del mouse'; // Hover
$_MODULE['<{layerslider}prestashop>_68eec46437c384d8dad18d5464ebc35c'] = 'Sempre'; // Always
$_MODULE['<{layerslider}prestashop>_7bf523564ae99db42b76b16f8a2231b0'] = 'Larghezza contenitore miniature'; // Thumbnail container width
$_MODULE['<{layerslider}prestashop>_c8ce45413d4b7aa40a23c487e35f9fef'] = 'La larghezza dell\'area delle miniature rispetto alla dimensione dello slider.'; // The width of the thumbnail area relative to the slider size.
