$_MODULE['<{layerslider}prestashop>_3175b94fbe567e891def2d97b9a82fff'] = 'L\'altezza delle miniature nell\'area di navigazione.'; // The height of thumbnails in the navigation area.
$_MODULE['<{layerslider}prestashop>_65819e181559efbeb04058d188bb09a2'] = 'Opacità miniatura attiva'; // Active thumbnail opacity
$_MODULE['<{layerslider}prestashop>_523fba24580483001fada8bd036680e9'] = 'Opacità in percentuale della miniatura della slide attiva.'; // Opacity in percentage of the active slide's thumbnail.
$_MODULE['<{layerslider}prestashop>_cf0f741e96ca0952f1ba77b54480a454'] = 'Opacità miniatura inattiva'; // Inactive thumbnail opacity
$_MODULE['<{layerslider}prestashop>_0ab5c1176a644398a9b4561891cf1e92'] = 'Opacità in percentuale delle miniature delle slide inattive.'; // Opacity in percentage of inactive slide thumbnails.
$_MODULE['<{layerslider}prestashop>_f66c60868ee78081b27e781f10b59cfd'] = 'Riproduci video automaticamente'; // Automatically play videos
$_MODULE['<{layerslider}prestashop>_2458c5b1cdaebce036e994a888804cc8'] = 'I video verranno avviati automaticamente sulla slide attiva.'; // Videos will be automatically started on the active slide.
$_MODULE['<{layerslider}prestashop>_f94ef77b4a2484acab460dc51c39eae5'] = 'Lo slideshow può essere temporaneamente messo in pausa mentre i video sono in riproduzione. Puoi scegliere di interrompere permanentemente la pausa fino al riavvio manuale.'; // The slideshow can temporally be paused while videos are playing. You can choose to permanently stop the pause until manual restarting.
$_MODULE['<{layerslider}prestashop>_dacc03bb6106a6c64fc7594f444cb0cd'] = 'Durante la riproduzione'; // While playing
$_MODULE['<{layerslider}prestashop>_d69deab82e6473366a7dcdffc6d50857'] = 'Permanentemente'; // Permanently
$_MODULE['<{layerslider}prestashop>_fa46ea6f6f6623fdd7039b5f1a8f3940'] = 'Nessuna azione'; // No action
$_MODULE['<{layerslider}prestashop>_4cae6acadf866d95afb764b4e6545be5'] = 'Anteprima Youtube'; // Youtube preview
$_MODULE['<{layerslider}prestashop>_a5ade6e166855925e2f6ea1f1cd50a8c'] = 'La qualità dell\'immagine di anteprima recuperata automaticamente per i video di YouTube quando non ne imposti una tua. Tieni presente che alcuni video non hanno anteprime HD e potresti dover scegliere una qualità inferiore.'; // The automatically fetched preview image quaility for YouTube videos when you do not set your own. Please note, some videos do not have HD previews, and you may need to choose a lower quaility.
$_MODULE['<{layerslider}prestashop>_155a657eee2a2e2b07c3a47b93c478f6'] = 'Qualità massima'; // Maximum quality
$_MODULE['<{layerslider}prestashop>_b8924eb7fe4c3fb0219f7709d999acb6'] = 'Alta qualità'; // High quality
$_MODULE['<{layerslider}prestashop>_31186f925fe95370a86649eb2b2e00c3'] = 'Qualità media'; // Medium quality
$_MODULE['<{layerslider}prestashop>_722597fc491a17f65a7b2c9db01ec6b1'] = 'Qualità predefinita'; // Default quality
$_MODULE['<{layerslider}prestashop>_be0233bf54a7d9579cbf0356bce96b17'] = 'Usa URL relativi'; // Use relative URLs
$_MODULE['<{layerslider}prestashop>_ba82cbe6dc7a81f3d77fabb6d414c0ee'] = 'Usa URL relativi per le immagini locali. Questa impostazione potrebbe essere importante quando si sposta l\'installazione di PS.'; // Use relative URLs for local images. This setting could be important when moving your PS installation.
$_MODULE['<{layerslider}prestashop>_c878cdf0cb53e7dbeb791eab13b84146'] = 'Consenti riavvio slide al ridimensionamento'; // Allow restarting slides on resize
$_MODULE['<{layerslider}prestashop>_0296ddaa31acdc8e379a3de8412aff9a'] = 'Certe opzioni di trasformazione e transizione non possono essere aggiornate al volo quando la dimensione del browser o l\'orientamento del dispositivo cambiano. Abilitando questa opzione, lo slider rileverà automaticamente tali situazioni e si riavvierà per preservare il suo aspetto.'; // Certain transformation and transition options cannot be updated on the fly when the browser size or device orientation changes. By enabling this option, the slider will automatically detect such situations and will restart the itself to preserve its appearance.
$_MODULE['<{layerslider}prestashop>_d9f1451d7e147a9d76732b903c85fd98'] = 'Usa attributo srcset'; // Use srcset attribute
$_MODULE['<{layerslider}prestashop>_d962a6678a6f57c0697bdba39433e0d7'] = 'L\'attributo srcset consente di caricare immagini ridimensionate dinamicamente in base alla risoluzione dello schermo. Può risparmiare banda e consentire l\'uso di immagini retina-ready su dispositivi ad alta risoluzione. In alcuni rari casi limite, questa opzione potrebbe causare immagini sfocate.'; // The srcset attribute allows loading dynamically scaled images based on screen resolution. It can save bandwidth and allow using retina-ready images on high resolution devices. In some rare edge cases, this option might cause blurry images.
$_MODULE['<{layerslider}prestashop>_806790e901a729799c42f26b23c5470f'] = 'Lazy load avanzato'; // Enhanced lazy load
$_MODULE['<{layerslider}prestashop>_bb477d8d7ee0d5561c80c51482d44904'] = 'Il comportamento di lazy loading predefinito fa un compromesso per garantire la massima compatibilità offrendo una soluzione che funziona idealmente in quasi tutti i casi. Tuttavia, lasciando intatto l\'attributo \'src\' dell\'immagine, c\'è una piccola possibilità che il browser possa iniziare a scaricare alcuni asset per una frazione di secondo prima che Creative Slider li annulli. Abilitare questa opzione eliminerà ogni possibilità di generare anche una quantità minima di traffico indesiderato, ma può anche causare problemi per l\'indicizzazione dei motori di ricerca e altri temi/moduli.'; // The default lazy loading behavior makes a compromise to ensure maximum compatibility while offering a solution that works ideally in almost all cases. However, by leaving the image ’src’ attribute untouched, there is a slight chance that the browser might start downloading some assets for a split second before Creative Slider cancels them. Enabling this option will eliminate any chance of generating even a minuscule amount of unwanted traffic, but it can also cause issues for search engine indexing and other themes/modules.
$_MODULE['<{layerslider}prestashop>_451af3f11142c7626d839eb7674d3e0a'] = 'Preferisci Modalità di Fusione'; // Prefer Blend Mode
$_MODULE['<{layerslider}prestashop>_6da524b45307ee7baa37799db0cd4796'] = 'Abilita questa opzione per evitare problemi di modalità di fusione con le transizioni delle slide. A causa di limitazioni tecniche, questo ritaglierà anche le transizioni delle slide indipendentemente dalle tue impostazioni.'; // Enable this option to avoid blend mode issues with slide transitions. Due to technical limitations, this will also clip your slide transitions regardless of your settings.
$_MODULE['<{layerslider}prestashop>_00d23a76e43b46dae9ec7aa9dcbebb32'] = 'Abilitato'; // Enabled
$_MODULE['<{layerslider}prestashop>_5e1575919121f7253b56bb39b99e1042'] = 'TuoLogo'; // YourLogo
$_MODULE['<{layerslider}prestashop>_367a210257e2ea49914c4a695f8abf70'] = 'Un livello immagine fisso può essere mostrato sopra lo slider che rimane fermo per tutto lo slider. Può essere usato per visualizzare loghi o watermark.'; // A fixed image layer can be shown above the slider that remains still throughout the whole slider. Can be used to display logos or watermarks.
$_MODULE['<{layerslider}prestashop>_77c34b7517dd216292658ee3b420dd1f'] = 'Stile TuoLogo'; // YourLogo style
$_MODULE['<{layerslider}prestashop>_355a12e47302b7e2627dc90d1c0e79c6'] = 'Proprietà CSS per controllare il posizionamento e l\'aspetto dell\'immagine.'; // CSS properties to control the image placement and appearance.
$_MODULE['<{layerslider}prestashop>_1cfb56506d3621c27196a6aa02a23c39'] = 'Link TuoLogo'; // YourLogo link
$_MODULE['<{layerslider}prestashop>_7966bee26ee8f49f0c5693a3b25a3461'] = 'Inserisci un URL per collegare l\'immagine TuoLogo.'; // Enter a URL to link the YourLogo image.
$_MODULE['<{layerslider}prestashop>_5afb14c537c0ed4ed3805e8f9c12ae68'] = 'Target del link'; // Link target
$_MODULE['<{layerslider}prestashop>_61c717e4d8c25d8ea4fe003f88675e74'] = 'Apri nella stessa pagina'; // Open on the same page
$_MODULE['<{layerslider}prestashop>_98a0075b23373e991f18c15fb8442d8b'] = 'Apri in una nuova pagina'; // Open on new page
$_MODULE['<{layerslider}prestashop>_67c48b3d90f5ae44e816fe1030452fb3'] = 'Apri nel frame genitore'; // Open in parent frame
$_MODULE['<{layerslider}prestashop>_e106bc3e705b4e24fe60a249e11c6f01'] = 'Apri nel frame principale'; // Open in main frame
$_MODULE['<{layerslider}prestashop>_b77006f2d0398fa7e68ef1a893ef850c'] = 'ID Articolo'; // Post ID
$_MODULE['<{layerslider}prestashop>_e4d99041f9e5af92b38767d09947600e'] = 'Titolo Articolo'; // Post Title
$_MODULE['<{layerslider}prestashop>_b5e6d43af159d5d593ca7c4b6db55491'] = 'Numero di Commenti'; // Number of Comments
$_MODULE['<{layerslider}prestashop>_cf3fb1ff52ea1eed3347ac5401ee7f0c'] = 'Ascendente'; // Ascending
$_MODULE['<{layerslider}prestashop>_e3cf5ac19407b1a62c6fccaff675a53b'] = 'Discendente'; // Descending
$_MODULE['<{layerslider}prestashop>_1a3cb622f5613168ed16ba4ffcfe49fe'] = 'Imposta un\'immagine per la slide'; // Set a slide image
$_MODULE['<{layerslider}prestashop>_1cf966e0716f7f365751df6e4a86f43f'] = 'L\'immagine/sfondo della slide. Clicca sull\'immagine per aprire il Gestore Immagini per scegliere o caricare un\'immagine.'; // The slide image/background. Click on the image to open the Image Manager to choose or upload an image.
$_MODULE['<{layerslider}prestashop>_6f6cb72d544962fa333e2e34ce64f719'] = 'Dimensione'; // Size
$_MODULE['<{layerslider}prestashop>_13eac5a039bc8041315fe1165a245a98'] = 'La dimensione dell\'immagine di sfondo della slide. Lascia questa opzione su "eredita" se vuoi impostarla globalmente dalle Impostazioni dello Slider.'; // The size of the slide background image. Leave this option on inherit if you want to set it globally from Slider Settings.
$_MODULE['<{layerslider}prestashop>_c49484faf79e2388b580e49444d6ac11'] = 'Eredita'; // Inherit
$_MODULE['<{layerslider}prestashop>_52f5e0bc3859bc5f5e25130b6c7e8881'] = 'Posizione'; // Position
$_MODULE['<{layerslider}prestashop>_25824be059f35ecadb2d38a895f7e710'] = 'La posizione dell\'immagine di sfondo della slide. Lascia questa opzione su "eredita" se vuoi impostarla globalmente dalle Impostazioni dello Slider.'; // The position of the slide background image. Leave this option on inherit if you want to set it globally from Slider Settings.
$_MODULE['<{layerslider}prestashop>_cb5feb1b7314637725a2e73bdc9f7295'] = 'Colore'; // Color
$_MODULE['<{layerslider}prestashop>_9880a2532d7550cb4bef6c24ce2275f3'] = 'Il colore di sfondo della slide. Puoi usare nomi di colori, valori esadecimali, RGB o RGBA.'; // The slide background color. You can use color names, hexadecimal, RGB or RGBA values.
$_MODULE['<{layerslider}prestashop>_9d8cfafeba857023956c26437b6570fc'] = 'Imposta una miniatura per la slide'; // Set a slide thumbnail
$_MODULE['<{layerslider}prestashop>_b95232d8c69a9f62cd6dab61887acf0f'] = 'L\'immagine in miniatura di questa slide. Clicca sull\'immagine per aprire il Gestore Immagini per scegliere o caricare un\'immagine. Se lasci questo campo vuoto, verrà usata l\'immagine della slide.'; // The thumbnail image of this slide. Click on the image to open the Image Manager to choose or upload an image. If you leave this field empty, the slide image will be used.
$_MODULE['<{layerslider}prestashop>_e02d2ae03de9d493df2b6b2d2813d302'] = 'Durata'; // Duration
$_MODULE['<{layerslider}prestashop>_b0c71ca949422ff07096787e513bf3dc'] = 'Qui puoi impostare l\'intervallo di tempo tra i cambi di slide, questa slide rimarrà visibile per il tempo specificato qui. Questo valore è in millisecondi, quindi il valore 1000 significa 1 secondo. Per favore non usare 0 o valori molto bassi.'; // Here you can set the time interval between slide changes, this slide will stay visible for the time specified here. This value is in millisecs, so the value 1000 means 1 second. Please don't use 0 or very low values.
$_MODULE['<{layerslider}prestashop>_4357cfb0b7acc1db400c94094794ae17'] = 'Abbiamo realizzato le nostre transizioni di slide predefinite con particolare cura per adattarsi alla maggior parte dei casi d\'uso. Tuttavia, se desideri aumentare o diminuire la velocità di queste transizioni, puoi sovrascrivere la loro durata qui fornendo la tua durata di transizione in millisecondi. (1 secondo = 1000 millisecondi)'; // We've made our pre-defined slide transitions with special care to fit in most use cases. However, if you would like to increase or decrease the speed of these transitions, you can override their timing here by providing your own transition length in milliseconds. (1 second = 1000 milliseconds)
$_MODULE['<{layerslider}prestashop>_38912a644194123a9ee9d01e126fcfae'] = 'durata personalizzata'; // custom duration
$_MODULE['<{layerslider}prestashop>_1605a4f4a4e45503d3ac914de9fba80a'] = 'Sfasamento Temporale'; // Time Shift
$_MODULE['<{layerslider}prestashop>_6d106138f5fadb601a337fca4d4b7a2e'] = 'Puoi spostare il punto di partenza della timeline dell\'animazione della slide, in modo che i livelli possano animarsi prima dopo un cambio di slide. Questo valore è in millisecondi. Un secondo equivale a 1000 millisecondi. Puoi usare solo un valore negativo.'; // You can shift the starting point of the slide animation timeline, so layers can animate in an earlier time after a slide change. This value is in milliseconds. A second is 1000 milliseconds. You can only use a negative value.
$_MODULE['<{layerslider}prestashop>_e1f70f4a4265cb51c1b219aa60eaa441'] = 'Inserisci URL'; // Enter URL
$_MODULE['<{layerslider}prestashop>_cfdb83fef5ccd56abb3592f98391b355'] = 'Se vuoi collegare l\'intera slide, digita l\'URL qui. Puoi scegliere una delle opzioni predefinite dalla lista a discesa quando clicchi in questo campo. Puoi anche digitare un cancelletto seguito da un numero per collegare questo livello a un\'altra slide. Esempio: #3 - questo passerà alla terza slide.'; // If you want to link the whole slide, type the URL here. You can choose one of the pre-defined options from the dropdown list when you click into this field. You can also type a hash mark followed by a number to link this layer to another slide. Example: #3 - this will switch to the third slide.
$_MODULE['<{layerslider}prestashop>_1f7412ef1f7fdba3cc269af9a0b7a40c'] = 'Target del Link'; // Link Target
$_MODULE['<{layerslider}prestashop>_e82688575274fd1ba522f5044431cc93'] = 'Scorri fino all\'elemento (Inserisci selettore)'; // Scroll to element (Enter selector)
$_MODULE['<{layerslider}prestashop>_1fc71d8275be86e2787bc4a8f0d62c84'] = 'Scegli se il link della slide debba trovarsi sopra o sotto i tuoi livelli. L\'ultima opzione rende il link cliccabile solo negli spazi vuoti dove lo sfondo della slide è visibile, e ti permette di collegare sia le slide che i livelli indipendentemente l\'uno dall\'altro.'; // Choose whether the slide link should be on top or underneath your layers. The later option makes the link clickable only at empty spaces where the slide background is visible, and enables you to link both slides and layers independently from each other.
$_MODULE['<{layerslider}prestashop>_7e04fe64ab136e31d62fcc6ea113f1ca'] = 'Sopra i livelli'; // On top of layers
$_MODULE['<{layerslider}prestashop>_d722a275a3f48eb46d892c9df863e1af'] = 'Sotto i livelli'; // Underneath layers
$_MODULE['<{layerslider}prestashop>_739cea2b85156183f917f2ccaa10a50c'] = '#ID'; // #ID
$_MODULE['<{layerslider}prestashop>_06f695600f91bfbd579d9d8f5a0147bd'] = 'Puoi applicare un attributo ID all\'elemento HTML di questa slide per lavorarci nel tuo codice CSS o Javascript personalizzato.'; // You can apply an ID attribute on the HTML element of this slide to work with it in your custom CSS or Javascript code.
$_MODULE['<{layerslider}prestashop>_550dc007dba485adc22eddfe0af40a81'] = 'Deeplink'; // Deeplink
$_MODULE['<{layerslider}prestashop>_070cb374111546db9ae4642406963ebd'] = 'Puoi specificare un nome alias per la slide che puoi usare nei tuoi URL con un cancelletto, così Creative Slider inizierà con la slide corrispondente.'; // You can specify a slide alias name which you can use in your URLs with a hash mark, so Creative Slider will start with the correspondig slide.
$_MODULE['<{layerslider}prestashop>_436e4906cf91bb911a38eb161e858a69'] = 'Hover Globale'; // Global Hover
$_MODULE['<{layerslider}prestashop>_f22bc2f96ed30d26a29060598c44c2fa'] = 'Attivando questa opzione, tutti i livelli attiveranno le loro transizioni di hover contemporaneamente quando passi il mouse sopra lo slider. È utile per creare effetti spettacolari che coinvolgono più transizioni di livello e si attivano al passaggio del mouse sullo slider invece che sui singoli livelli.'; // By turning this option on, all layers will trigger their Hover Transitions at the same time when you hover over the slider with your mouse cursor. It’s useful to create spectacular effects that involve multiple layer transitions and activate on hovering over the slider instead of individual layers.
$_MODULE['<{layerslider}prestashop>_7acdf85c69cc3c5305456a293524386e'] = 'Nascosto'; // Hidden
$_MODULE['<{layerslider}prestashop>_a494a9272210a3aa3682f9fa8b6ad9fc'] = 'Se non vuoi usare questa slide nella tua home page, ma vuoi conservarla, puoi nasconderla con questo interruttore.'; // If you don't want to use this slide in your front-page, but you want to keep it, you can hide it with this switch.
$_MODULE['<{layerslider}prestashop>_d33fd48027b557f5bcb3f15a238d7537'] = 'Livelli in overflow'; // Overflow layers
$_MODULE['<{layerslider}prestashop>_5bbae9c02b64de11da4d22707a297710'] = 'Per impostazione predefinita, lo slider ritaglia i livelli al di fuori dei suoi confini. Abilita questa opzione per consentire il contenuto in overflow.'; // By default the slider clips the layers outside of its bounds. Enable this option to allow overflowing content.
$_MODULE['<{layerslider}prestashop>_57ffe7327fb6fb004c59466a978c4100'] = 'Inizia il'; // Start on
$_MODULE['<{layerslider}prestashop>_6ba9104be4da1fea318c02faca91dad6'] = 'La slide programmata sarà visibile ai tuoi visitatori solo nel periodo di tempo che imposti qui.<br>Stiamo usando il formato internazionale di data e ora per evitare ambiguità.'; // Scheduled slide will only be visible to your visitors between the time period you set here.<br>We're using international date and time format to avoid ambiguity.
$_MODULE['<{layerslider}prestashop>_6ea6d7b483daeb9be3acaad212b04181'] = 'Termina il'; // Stop on
$_MODULE['<{layerslider}prestashop>_b78a3223503896721cca1303f776159b'] = 'Titolo'; // Title
$_MODULE['<{layerslider}prestashop>_a2e92861b757ab878312dd57993d60cf'] = 'Alt'; // Alt
$_MODULE['<{layerslider}prestashop>_f17b29e841d3183298a453dc423242a0'] = 'Assegna un nome o descrivi l\'immagine della tua slide, in modo che i motori di ricerca e i software di lettura vocale possano identificarla correttamente.'; // Name or describe your slide image, so search engines and VoiceOver softwares can properly identify it.
$_MODULE['<{layerslider}prestashop>_4252b72e6ebcd4d4b4c2e46a786f03d2'] = 'Zoom'; // Zoom
$_MODULE['<{layerslider}prestashop>_f5ca4abce85e2dddb0342d0bae3a7270'] = 'Zoom Avanti'; // Zoom In
$_MODULE['<{layerslider}prestashop>_30850b501f98539b1aabaa29fabe41ef'] = 'Zoom Indietro'; // Zoom Out
$_MODULE['<{layerslider}prestashop>_8d2de5368588552fbae54044ac5c7b3d'] = 'Rotazione'; // Rotate
$_MODULE['<{layerslider}prestashop>_8aa2fa2e684ba408f551f3504c47427e'] = 'La quantità di rotazione (se presente) in gradi utilizzata nell\'effetto Ken Burns. Sono consentiti valori negativi per la rotazione in senso antiorario.'; // The amount of rotation (if any) in degrees used in the Ken Burns effect. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_85a7cd587d6142dbfc1a4de05af7b75d'] = 'Scala'; // Scale
$_MODULE['<{layerslider}prestashop>_2ed8e1d37be922f23b2713c3e69a85ae'] = 'Aumenta o diminuisci la dimensione dell\'immagine di sfondo della slide nell\'effetto Ken Burns. Il valore predefinito è 1, il valore 2 raddoppierà l\'immagine, mentre 0.5 risulterà in metà della dimensione. I valori negativi capovolgeranno l\'immagine.'; // Increase or decrease the size of the slide background image in the Ken Burns effect. The default value is 1, the value 2 will double the image, while 0.5 results half the size. Negative values will flip the image.
$_MODULE['<{layerslider}prestashop>_a1fa27779242b4902f7ae3bdd5c6d508'] = 'Tipo'; // Type
$_MODULE['<{layerslider}prestashop>_4a2d97fd5296d09fea3cbe45d107a7b3'] = 'Il valore predefinito per i livelli parallasse su questa slide, che erediteranno, a meno che non lo imposti diversamente sui livelli interessati.'; // The default value for parallax layers on this slide, which they will inherit, unless you set it otherwise on the affected layers.
$_MODULE['<{layerslider}prestashop>_8c94134f25efe7680f9743b2774e8e1f'] = '2D'; // 2D
$_MODULE['<{layerslider}prestashop>_76aa96369abbba52e621bfa83da8e64f'] = '3D'; // 3D
$_MODULE['<{layerslider}prestashop>_a4ecfc70574394990cf17bd83df499f7'] = 'Evento'; // Event
$_MODULE['<{layerslider}prestashop>_87932092d26d18e63889036bbf70518e'] = 'Puoi attivare l\'effetto parallasse scorrendo la pagina, oppure muovendo il cursore del mouse / inclinando il tuo dispositivo mobile. Questo è il valore predefinito su questa slide, che i livelli parallasse erediteranno, a meno che non lo imposti diversamente direttamente su di essi.'; // You can trigger the parallax effect by either scrolling the page, or by moving your mouse cursor / tilting your mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_58af070b9f7f3dc090af0ece708e8869'] = 'Cursore o Inclinazione'; // Cursor or Tilt
$_MODULE['<{layerslider}prestashop>_61ca8fa7a7c8b4699523bc8773c306d0'] = 'Assi'; // Axes
$_MODULE['<{layerslider}prestashop>_fc888362a84b5b975136bbca8e1fc5c6'] = 'Scegli su quali assi i livelli parallasse devono muoversi. Questo è il valore predefinito su questa slide, che i livelli parallasse erediteranno, a meno che non lo imposti diversamente direttamente su di essi.'; // Choose on which axes parallax layers should move. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_6adf97f83acf6453d4a6a4b1070f3754'] = 'Nessuno'; // None
$_MODULE['<{layerslider}prestashop>_2c452204ed58a6f4a3bcda80344b338a'] = 'Entrambi gli assi'; // Both axes
$_MODULE['<{layerslider}prestashop>_ad09aaae9c9ffe403ffdb2a6568f5a36'] = 'Solo orizzontale'; // Horizontal only
$_MODULE['<{layerslider}prestashop>_354908b89248f3dcbab970b32860a331'] = 'Solo verticale'; // Vertical only
$_MODULE['<{layerslider}prestashop>_8b622b0a6ecf4e0116eaf248876f8700'] = 'Origine Trasformazione'; // Transform Origin
$_MODULE['<{layerslider}prestashop>_e5a904ff73268b65730e4fb8b6127bf1'] = 'Imposta un punto sul canvas da cui vengono calcolate le trasformazioni. Ad esempio, un livello può ruotare attorno al suo asse centrale o un punto completamente personalizzato, come uno dei suoi angoli. I tre valori rappresentano gli assi X, Y e Z nello spazio 3D. Oltre ai valori in pixel e percentuale, puoi anche usare le seguenti costanti: top, right, bottom, left, center.'; // Sets a point on canvas from which transformations are calculated. For example, a layer may rotate around its center axis or a completely custom point, such as one of its corners. The three values represent the X, Y and Z axes in 3D space. Apart from the pixel and percentage values, you can also use the following constants: top, right, bottom, left, center.
$_MODULE['<{layerslider}prestashop>_97289d779de759c4fe3a0ef9d3a4ff3d'] = 'Durata movimento'; // Move duration
$_MODULE['<{layerslider}prestashop>_ef82e470cae5696da7dc47e9a50fa8f7'] = 'Controlla la velocità di animazione dei livelli quando muovi il cursore del mouse o inclini il tuo dispositivo mobile. Questo è il valore predefinito su questa slide, che i livelli parallasse erediteranno, a meno che non lo imposti diversamente direttamente su di essi.'; // Controls the speed of animating layers when you move your mouse cursor or tilt your mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_0bdd8970e06688e4a6ad694b8ed7b9f7'] = 'Durata uscita'; // Leave duration
$_MODULE['<{layerslider}prestashop>_9aa9b8945ad7ff74e04fb53dbbe3d1f2'] = 'Controlla la rapidità con cui i tuoi livelli tornano alla loro posizione originale quando sposti il cursore del mouse fuori da uno slider parallasse. Questo valore è in millisecondi. 1 secondo = 1000 millisecondi. Questo è il valore predefinito su questa slide, che i livelli parallasse erediteranno, a meno che non lo imposti diversamente direttamente su di essi.'; // Controls how quickly your layers revert to their original position when you move your mouse cursor outside of a parallax slider. This value is in milliseconds. 1 second = 1000 milliseconds. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_0aa6f4210bf373c95eda00232e93cd98'] = 'Distanza'; // Distance
$_MODULE['<{layerslider}prestashop>_396950a091a406fcd6f9f4cc75927536'] = 'Aumenta o diminuisci la quantità di movimento del livello quando sposti il cursore del mouse o inclini un dispositivo mobile. Questo è il valore predefinito su questa slide, che i livelli parallasse erediteranno, a meno che non lo imposti diversamente direttamente su di essi.'; // Increase or decrease the amount of layer movement when moving your mouse cursor or tilting on a mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_f1a42bd417390fc63b030a519624607a'] = 'Rotazione'; // Rotation
$_MODULE['<{layerslider}prestashop>_331ee65576c7333ba77a13d691219105'] = 'Aumenta o diminuisci la quantità di rotazione del livello nello spazio 3D quando sposti il cursore del mouse o inclini un dispositivo mobile. Questo è il valore predefinito su questa slide, che i livelli parallasse erediteranno, a meno che non lo imposti diversamente direttamente su di essi.'; // Increase or decrease the amount of layer rotation in the 3D space when moving your mouse cursor or tilting on a mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_a80420eef88d11f77532f1b9cb467fa3'] = 'Prospettiva'; // Perspective
$_MODULE['<{layerslider}prestashop>_7ba7448042bdf18c7669bec909a0a7be'] = 'Cambia la prospettiva dei livelli nello spazio 3D. Questo è il valore predefinito su questa slide, che i livelli parallasse erediteranno, a meno che non lo imposti diversamente direttamente su di essi.'; // Changes the perspective of layers in the 3D space. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_d6432a4413208eee54d613ceb82f726a'] = 'Filtro Da'; // Filter From
$_MODULE['<{layerslider}prestashop>_bd3ec381eecf6eb78c9a97594745d33c'] = 'I filtri forniscono effetti come la sfocatura o il cambio di colore dei tuoi livelli. Clicca nel campo di testo per vedere una selezione di filtri che puoi usare. Anche se cliccare sulle opzioni predefinite resetterà il campo di testo, puoi applicare più filtri semplicemente fornendo un elenco separato da spazi di tutti i filtri che desideri utilizzare.'; // Filters provide effects like blurring or color shifting your layers. Click into the text field to see a selection of filters you can use. Although clicking on the pre-defined options will reset the text field, you can apply multiple filters simply by providing a space separated list of all the filters you would like to use.
$_MODULE['<{layerslider}prestashop>_6b770358764a885d6dc7f2be20604356'] = 'Filtro A'; // Filter To
$_MODULE['<{layerslider}prestashop>_05b1dc77590105a18fc4c02526fe0c7a'] = 'Autoplay'; // Autoplay
$_MODULE['<{layerslider}prestashop>_2b3de50de6ab7bd0aaf46ae654032790'] = 'Mostra Info'; // Show Info
$_MODULE['<{layerslider}prestashop>_24b6472fcfa59cddd3f7bbc326582b5f'] = 'Controlli'; // Controls
$_MODULE['<{layerslider}prestashop>_58bccbc47e6de6783fb90fd62890a171'] = 'Modalità di riempimento'; // Fill mode
$_MODULE['<{layerslider}prestashop>_bd7a9717d29c5ddcab1bc175eda1e298'] = 'Volume'; // Volume
$_MODULE['<{layerslider}prestashop>_56a7f02a3b02e4a16864670ff48745e1'] = 'Usa questo video come sfondo della slide'; // Use this video as slide background
$_MODULE['<{layerslider}prestashop>_4ee3787bc7df95d25272524868e60d4d'] = 'Forza questo livello ad agire come lo sfondo della slide coprendo l\'intero slider e ignorando alcune transizioni. Assicurati di fornire la tua immagine poster con l\'opzione sopra, in modo che lo slider possa visualizzarla immediatamente al caricamento della pagina.'; // Forces this layer to act like the slide background by covering the whole slider and ignoring some transitions. Please make sure to provide your own poster image with the option above, so the slider can display it immediately on page load.
$_MODULE['<{layerslider}prestashop>_9d16dd63ee0afa947dc998fb3d5a4a96'] = 'Scegli un\'immagine di sovrapposizione:'; // Choose an overlay image:
$_MODULE['<{layerslider}prestashop>_e13b4cc51565c9030f943e31c253c8aa'] = 'Copri i tuoi video con un\'immagine di sovrapposizione per avere effetti a punti o a strisce su di essi.'; // Cover your videos with an overlay image to have dotted or striped effects on them.
$_MODULE['<{layerslider}prestashop>_1529fb44e04df26ff7666faa9f58c605'] = 'ScostamentoX'; // OffsetX
$_MODULE['<{layerslider}prestashop>_0d12fb40782d7877c5018ff4b501e701'] = 'Sposta la posizione di partenza del livello dal suo originale sull\'asse orizzontale del numero di pixel dato. Usa valori negativi per la direzione opposta. I valori percentuali sono relativi alla larghezza di questo livello. I valori \'left\' o \'right\' posizionano il livello fuori dall\'area di staging, in modo che entri in scena da entrambi i lati durante l\'animazione verso la sua destinazione.'; // Shifts the layer starting position from its original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position the layer out the staging area, so it enters the scene from either side when animating to its destination location.
$_MODULE['<{layerslider}prestashop>_1508a7d829d65cf5e117fdc2aca0f155'] = 'ScostamentoY'; // OffsetY
$_MODULE['<{layerslider}prestashop>_c91f704c049f7d06fe50106d7452c21c'] = 'Sposta la posizione di partenza del livello dal suo originale sull\'asse verticale del numero di pixel dato. Usa valori negativi per la direzione opposta. I valori percentuali sono relativi all\'altezza di questo livello. I valori \'top\' o \'bottom\' posizionano il livello fuori dall\'area di staging, in modo che entri in scena da entrambi i lati verticali durante l\'animazione verso la sua destinazione.'; // Shifts the layer starting position from its original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the height of this layer. The values 'top' or 'bottom' position the layer out the staging area, so it enters the scene from either vertical side when animating to its destination location.
$_MODULE['<{layerslider}prestashop>_7686cf30c00c9f146a9224a33ba99a0f'] = 'La durata della transizione in millisecondi quando il livello entra in scena. Un secondo equivale a 1000 millisecondi.'; // The length of the transition in milliseconds when the layer enters the scene. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_f2572c86c0aff2b2b7a92fbb6dee1491'] = 'Inizia a'; // Start at
$_MODULE['<{layerslider}prestashop>_1f413844a6a15351c7a32a16ce962bfd'] = 'Ritarda la transizione della quantità di millisecondi data prima che il livello entri in scena. Un secondo equivale a 1000 millisecondi.'; // Delays the transition with the given amount of milliseconds before the layer enters the scene. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_32485d52ad7aea25b3bc80d416e76a3b'] = 'Easing'; // Easing
$_MODULE['<{layerslider}prestashop>_ca9a3cf0ea2e65cd611fe23633cd1186'] = 'La funzione di temporizzazione dell\'animazione. Con questa funzione puoi manipolare il movimento dell\'oggetto animato. Clicca sul link accanto a questo campo di selezione per aprire easings.net per maggiori informazioni ed esempi in tempo reale.'; // The timing function of the animation. With this function you can manipulate the movement of the animated object. Please click on the link next to this select field to open easings.net for more information and real-time examples.
$_MODULE['<{layerslider}prestashop>_04e0385c10aefee8e4681617d2f3ef40'] = 'Dissolvenza'; // Fade
$_MODULE['<{layerslider}prestashop>_ecdc93d174113fe69b7cbf2c42b5a1cb'] = 'Dissolvi il livello durante la transizione.'; // Fade the layer during the transition.
$_MODULE['<{layerslider}prestashop>_b98c4145f7f66383ce71bf31bc4850b2'] = 'Ruota il livello del numero di gradi dato. Sono ammessi valori negativi per la rotazione in senso antiorario.'; // Rotates the layer by the given number of degrees. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_801e0dd823542f625e0f2ee135efb62d'] = 'RotazioneX'; // RotateX
$_MODULE['<{layerslider}prestashop>_54f64742da0d7bd157ccaf54d4ac73a1'] = 'Ruota il livello lungo l\'asse X (orizzontale) del numero di gradi dato. Sono ammessi valori negativi per la direzione inversa.'; // Rotates the layer along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_ea0928ab345567847020e1544892fba0'] = 'RotazioneY'; // RotateY
$_MODULE['<{layerslider}prestashop>_209eea8f9d8a60293098e07e8951e156'] = 'Ruota il livello lungo l\'asse Y (verticale) del numero di gradi dato. Sono ammessi valori negativi per la direzione inversa.'; // Rotates the layer along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_5a013b463ee01be2924568775fdddfb1'] = 'InclinazioneX'; // SkewX
$_MODULE['<{layerslider}prestashop>_253108f96bfad9912bb2178a4c7aef73'] = 'Inclina il livello lungo l\'asse X (orizzontale) del numero di gradi dato. Sono ammessi valori negativi per la direzione inversa.'; // Skews the layer along the X (horizontal) by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_eeb66258f8bf4bb3c0763461b5c1797d'] = 'InclinazioneY'; // SkewY
$_MODULE['<{layerslider}prestashop>_9d19b1698a8b2f7b0efa8c91067053dd'] = 'Inclina il livello lungo l\'asse Y (verticale) del numero di gradi dato. Sono ammessi valori negativi per la direzione inversa.'; // Skews the layer along the Y (vertical) by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_b5e0c179725e7f282ffb8e6a96797b49'] = 'ScalaX'; // ScaleX
$_MODULE['<{layerslider}prestashop>_15cfa2ea26e51b8489ace013f1b2ec5c'] = 'Scala il livello lungo l\'asse X (orizzontale) del vettore specificato. Usa il valore 1 per la dimensione originale. Il valore 2 raddoppierà, mentre 0.5 ridurrà il livello rispetto alla sua dimensione originale.'; // Scales the layer along the X (horizontal) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks the layer compared to its original size.
$_MODULE['<{layerslider}prestashop>_3475b72c6483a5c871d245e2567c96c7'] = 'ScalaY'; // ScaleY
$_MODULE['<{layerslider}prestashop>_3db72901337b8e6eeaa04ffd8db52e5e'] = 'Scala il livello lungo l\'asse Y (verticale) del vettore specificato. Usa il valore 1 per la dimensione originale. Il valore 2 raddoppierà, mentre 0.5 ridurrà il livello rispetto alla sua dimensione originale.'; // Scales the layer along the Y (vertical) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks the layer compared to its original size.
$_MODULE['<{layerslider}prestashop>_e55d5d854ca64aed330e5591b62ae112'] = 'Imposta un punto sul canvas da cui vengono calcolate le trasformazioni. Ad esempio, un livello può ruotare attorno al suo asse centrale o un punto completamente personalizzato, come uno dei suoi angoli. I tre valori rappresentano gli assi X, Y e Z nello spazio 3D. Oltre ai valori in pixel e percentuale, puoi anche usare le seguenti costanti: top, right, bottom, left, center, slidercenter, slidermiddle, slidertop, sliderright, sliderbottom, sliderleft.'; // Sets a point on canvas from which transformations are calculated. For example, a layer may rotate around its center axis or a completely custom point, such as one of its corners. The three values represent the X, Y and Z axes in 3D space. Apart from the pixel and percentage values, you can also use the following constants: top, right, bottom, left, center, slidercenter, slidermiddle, slidertop, sliderright, sliderbottom, sliderleft.
$_MODULE['<{layerslider}prestashop>_4a18312b5b75f549d5551e5912ad6ebf'] = 'Maschera'; // Mask
$_MODULE['<{layerslider}prestashop>_7fb23cb4a33cca7e266b2deda0034711'] = 'Ritaglia (taglia) i lati del livello della quantità specificata in pixel o percentuali. I 4 valori in ordine: alto, destra, basso e lato sinistro del livello.'; // Clips (cuts off) the sides of the layer by the given amount specified in pixels or percentages. The 4 value in order: top, right, bottom and the left side of the layer.
$_MODULE['<{layerslider}prestashop>_a9ded1e5ce5d75814730bb4caaf49419'] = 'Sfondo'; // Background
$_MODULE['<{layerslider}prestashop>_57315a787bf5df775dcdb38f85aacf7b'] = 'Il colore di sfondo del tuo livello. Puoi usare nomi di colori, valori esadecimali, RGB o RGBA così come la parola chiave \'transparent\'. Esempio: #FFF'; // The background color of your layer. You can use color names, hexadecimal, RGB or RGBA values as well as the 'transparent' keyword. Example: #FFF
$_MODULE['<{layerslider}prestashop>_cdb3e9cc0b2932a6d1543d19732761f1'] = 'Il colore del tuo testo. Puoi usare nomi di colori, valori esadecimali, RGB o RGBA. Esempio: #333'; // The color of your text. You can use color names, hexadecimal, RGB or RGBA values. Example: #333
$_MODULE['<{layerslider}prestashop>_cabcfc0f365f0e649cf8c229bf54605e'] = 'Angoli Arrotondati'; // Rounded Corners
$_MODULE['<{layerslider}prestashop>_f0d205bfae354c2e65725ed59bc101e7'] = 'Se vuoi angoli arrotondati, puoi impostare il loro raggio qui in pixel. Esempio: 5px'; // If you want rounded corners, you can set its radius here in pixels. Example: 5px
$_MODULE['<{layerslider}prestashop>_32954654ac8fe66a1d09be19001de2d4'] = 'Larghezza'; // Width
$_MODULE['<{layerslider}prestashop>_de11d49b6bbf1b1ecd2b424dc1c0c74a'] = 'La larghezza iniziale di questo livello da cui verrà animato alla sua dimensione corretta durante la transizione.'; // The initial width of this layer from which it will be animated to its proper size during the transition.
$_MODULE['<{layerslider}prestashop>_eec6c4bdbd339edf8cbea68becb85244'] = 'Altezza'; // Height
$_MODULE['<{layerslider}prestashop>_4cc10791b724542e8a9a04636995d1f5'] = 'L\'altezza iniziale di questo livello da cui verrà animato alla sua dimensione corretta durante la transizione.'; // The initial height of this layer from which it will be animated to its proper size during the transition.
$_MODULE['<{layerslider}prestashop>_d7778d0c64b6ba21494c97f77a66885a'] = 'Filtro'; // Filter
$_MODULE['<{layerslider}prestashop>_3f6230752680291a660faeec55dc0b73'] = 'I filtri forniscono effetti come la sfocatura o il cambio di colore dei tuoi livelli. Clicca nel campo di testo per vedere una selezione di filtri che puoi usare. Anche se cliccare sulle opzioni predefinite resetterà il campo di testo, puoi applicare più filtri semplicemente fornendo un elenco separato da spazi di tutti i filtri che desideri utilizzare. Clicca sul link "Filtro" per maggiori informazioni.'; // Filters provide effects like blurring or color shifting your layers. Click into the text field to see a selection of filters you can use. Although clicking on the pre-defined options will reset the text field, you can apply multiple filters simply by providing a space separated list of all the filters you would like to use. Click on the "Filter" link for more information.
$_MODULE['<{layerslider}prestashop>_8cb8ac2653a6471f6779aa5c2d9cded2'] = 'Cambia la prospettiva di questo livello nello spazio 3D.'; // Changes the perspective of this layer in the 3D space.
$_MODULE['<{layerslider}prestashop>_cb1fa274044590e8c05e0e3fe44dd203'] = 'Sposta il livello dalla sua posizione originale sull\'asse orizzontale del numero di pixel dato. Usa valori negativi per la direzione opposta. I valori percentuali sono relativi alla larghezza di questo livello. I valori \'left\' o \'right\' animano il livello fuori dall\'area di staging, in modo che possa lasciare la scena da entrambi i lati.'; // Shifts the layer from its original position on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' animate the layer out the staging area, so it can leave the scene on either side.
$_MODULE['<{layerslider}prestashop>_aa243196666cd7d2c5e92dd0f8b9b5f4'] = 'Sposta il livello dalla sua posizione originale sull\'asse verticale del numero di pixel dato. Usa valori negativi per la direzione opposta. I valori percentuali sono relativi all\'altezza di questo livello. I valori \'top\' o \'bottom\' animano il livello fuori dall\'area di staging, in modo che possa lasciare la scena da entrambi i lati verticali.'; // Shifts the layer from its original position on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the height of this layer. The values 'top' or 'bottom' animate the layer out the staging area, so it can leave the scene on either vertical side.
$_MODULE['<{layerslider}prestashop>_f04f3b646758fcab3a12facb6373fdc0'] = 'La durata della transizione in millisecondi quando il livello lascia la slide. Un secondo equivale a 1000 millisecondi.'; // The length of the transition in milliseconds when the layer leaves the slide. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_b92bb5e60806c72def5363a5a8bb035e'] = 'Puoi impostare l\'ora di inizio di questa transizione. Usa una delle opzioni predefinite per usare una temporizzazione relativa, che può essere spostata con operazioni personalizzate.'; // You can set the starting time of this transition. Use one of the pre-defined options to use relative timing, which can be shifted with custom operations.
$_MODULE['<{layerslider}prestashop>_c36ace66cf4777473ba3200cf815253c'] = 'Inizio cambio slide (ignora modificatore)'; // Slide change starts (ignoring modifier)
$_MODULE['<{layerslider}prestashop>_371b285fa971d884eaebf156db4065c8'] = 'Fine transizione di apertura'; // Opening Transition completes
$_MODULE['<{layerslider}prestashop>_8920002666c88ed85ae80665159154f4'] = 'Inizio transizione testo di apertura'; // Opening Text Transition starts
