$_MODULE['<{layerslider}prestashop>_dc08824d508252f7973060a086788ec1'] = 'Fine transizioni di apertura, testo di apertura e loop'; // Opening, Opening Text and Loop Transitions complete
$_MODULE['<{layerslider}prestashop>_1fcb9ccb4471ff55ac855fcb38bd015b'] = 'Inizio transizione testo di chiusura'; // Ending Text Transition starts
