$_MODULE['<{layerslider}prestashop>_7094fc088dddef6adaa665620fe96dcc'] = 'Inclina il livello lungo l\'asse X (orizzontale) del numero di gradi dato. Sono ammessi valori negativi per la direzione inversa.'; // Skews the layer along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_049d4369eb664418bd75569e09641c99'] = 'Inclina il livello lungo l\'asse Y (verticale) del numero di gradi dato. Sono ammessi valori negativi per la direzione inversa.'; // Skews the layer along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_e9e245065a77b7927aaccb2cf9d2ffcd'] = 'Se non vuoi usare questo livello, ma vuoi conservarlo, puoi nasconderlo con questo interruttore.'; // If you don't want to use this layer, but you want to keep it, you can hide it with this switch.
$_MODULE['<{layerslider}prestashop>_630c4a18856c4ae057355c9398e83a32'] = 'Anima lo sfondo verso il colore che specifichi qui quando il livello lascia il canvas dello slider.'; // Animates the background toward the color you specify here when the layer leaves the slider canvas.
$_MODULE['<{layerslider}prestashop>_77064060d521c47a027e25dab869772f'] = 'Anima il colore del testo verso il colore che specifichi qui quando il livello lascia il canvas dello slider.'; // Animates the text color toward the color you specify here when the layer leaves the slider canvas.
$_MODULE['<{layerslider}prestashop>_f53e87a23a86051ea35dbfb9f14e6511'] = 'Anima gli angoli arrotondati verso il valore che specifichi qui quando il livello lascia il canvas dello slider.'; // Animates rounded corners toward the value you specify here when the layer leaves the slider canvas.
$_MODULE['<{layerslider}prestashop>_493d9e9e60d44f987c62cd0201269cb5'] = 'Anima la larghezza del livello verso il valore che specifichi qui quando il livello lascia il canvas dello slider.'; // Animates the layer width toward the value you specify here when the layer leaves the slider canvas.
$_MODULE['<{layerslider}prestashop>_78ad1defbcb0f83255f363b25c4e9494'] = 'Anima l\'altezza del livello verso il valore che specifichi qui quando il livello lascia il canvas dello slider.'; // Animates the layer height toward the value you specify here when the layer leaves the slider canvas.
$_MODULE['<{layerslider}prestashop>_69f18587841a5200e32c92bd1309ae37'] = 'Animazione Testo'; // Text Animation
$_MODULE['<{layerslider}prestashop>_e92ac60744c22808ee11554229245b7c'] = 'Seleziona come il tuo testo deve essere diviso e animato.'; // Select how your text should be split and animated.
$_MODULE['<{layerslider}prestashop>_0820eeb1c0c49e01eee5e73be6cbaa1b'] = 'per caratteri ascendente'; // by chars ascending
$_MODULE['<{layerslider}prestashop>_ce96c08d4cf2705fd383937da59c55fd'] = 'per caratteri discendente'; // by chars descending
$_MODULE['<{layerslider}prestashop>_86b6395565a2eadfc0b0ae256fb035fc'] = 'per caratteri casuale'; // by chars random
$_MODULE['<{layerslider}prestashop>_df1bc5915835bd215465d2f7ea32d5f5'] = 'per caratteri da centro a bordo'; // by chars center to edge
$_MODULE['<{layerslider}prestashop>_b871f5177b185a80f878b7bc0bc8d573'] = 'per caratteri da bordo a centro'; // by chars edge to center
$_MODULE['<{layerslider}prestashop>_a43dd45abfce50f180d398e3b52349df'] = 'per parole ascendente'; // by words ascending
$_MODULE['<{layerslider}prestashop>_dbd232eeb91f56a203a0ecf57454f52b'] = 'per parole discendente'; // by words descending
$_MODULE['<{layerslider}prestashop>_905601bb43ca936f21e8fa259c683932'] = 'per parole casuale'; // by words random
