$_MODULE['<{layerslider}prestashop>_19c45324c9ca36d31215f056839a28c8'] = 'Spostamento in Entrata'; // Shift In
$_MODULE['<{layerslider}prestashop>_02f41f49726759b91cf468825bdf41a2'] = 'Ritarda la transizione di ogni nodo di testo l\'uno rispetto all\'altro. Un secondo equivale a 1000 millisecondi.'; // Delays the transition of each text nodes relative to each other. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_3fff50b68e60ed555ff901b0fdfcd783'] = 'Sposta la posizione di partenza dei nodi di testo dalla loro originale sull\'asse orizzontale del numero di pixel dato. Usa valori negativi per la direzione opposta. I valori percentuali sono relativi alla larghezza di questo livello. I valori \'left\' o \'right\' posizionano i nodi di testo fuori dall\'area di staging, in modo che entrino in scena da entrambi i lati durante l\'animazione verso la loro destinazione. Elencando più valori separati da un carattere |, lo slider userà diverse variazioni di transizione su ogni nodo di testo ciclando tra i valori forniti.'; // Shifts the starting position of text nodes from their original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position text nodes out the staging area, so they enter the scene from either side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_e1d2fdcc944aa0f2e839f171f044d659'] = 'Sposta la posizione di partenza dei nodi di testo dalla loro originale sull\'asse verticale del numero di pixel dato. Usa valori negativi per la direzione opposta. I valori percentuali sono relativi alla larghezza di questo livello. I valori \'top\' o \'bottom\' posizionano i nodi di testo fuori dall\'area di staging, in modo che entrino in scena da entrambi i lati verticali durante l\'animazione verso la loro destinazione. Elencando più valori separati da un carattere |, lo slider userà diverse variazioni di transizione su ogni nodo di testo ciclando tra i valori forniti.'; // Shifts the starting position of text nodes from their original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'top' or 'bottom' position text nodes out the staging area, so they enter the scene from either vertical side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_968c58d8f1922a6b84d393c59a64a49c'] = 'La durata della transizione in millisecondi dei singoli frammenti di testo. Un secondo equivale a 1000 millisecondi.'; // The transition length in milliseconds of the individual text fragments. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_ca6c773be9bea589e35cd5932032450e'] = 'La funzione di temporizzazione dell\'animazione. Con questa funzione puoi manipolare il movimento dei frammenti di testo animati. Clicca sul link accanto a questo campo di selezione per aprire easings.net per maggiori informazioni ed esempi in tempo reale.'; // The timing function of the animation. With this function you can manipulate the movement of animated text fragments. Please click on the link next to this select field to open easings.net for more information and real-time examples.
$_MODULE['<{layerslider}prestashop>_218ff9f345230b14660e70e66162823f'] = 'Dissolvi i frammenti di testo durante la loro transizione.'; // Fade the text fragments during their transition.
$_MODULE['<{layerslider}prestashop>_87140560d2ebde43c1ee6bcbca46632b'] = 'IniziaA'; // StartAt
$_MODULE['<{layerslider}prestashop>_5ca3eda902c20e71f2b8a9b37d6400e9'] = 'Inizio transizione di apertura'; // Opening Transition starts
$_MODULE['<{layerslider}prestashop>_fff3063495dd33cf3909fa4b1a9bc98d'] = 'Ruota i frammenti di testo in senso orario del numero di gradi dato. Sono ammessi valori negativi per la rotazione in senso antiorario. Elencando più valori separati da un carattere |, lo slider userà diverse variazioni di transizione su ogni nodo di testo ciclando tra i valori forniti.'; // Rotates text fragments clockwise by the given number of degrees. Negative values are allowed for counterclockwise rotation. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_14f1aa4b97984dfcc375079b84f0eccc'] = 'Ruota i frammenti di testo lungo l\'asse X (orizzontale) del numero di gradi dato. Sono ammessi valori negativi per la direzione inversa. Elencando più valori separati da un carattere |, lo slider userà diverse variazioni di transizione su ogni nodo di testo ciclando tra i valori forniti.'; // Rotates text fragments along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_871c9bdc8e8606162c54996b7f3e3d55'] = 'Ruota i frammenti di testo lungo l\'asse Y (verticale) del numero di gradi dato. Sono ammessi valori negativi per la direzione inversa. Elencando più valori separati da un carattere |, lo slider userà diverse variazioni di transizione su ogni nodo di testo ciclando tra i valori forniti.'; // Rotates text fragments along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_fd776f8e6385f4f4e57c79701beb1f12'] = 'Scala i frammenti di testo lungo l\'asse X (orizzontale) del vettore specificato. Usa il valore 1 per la dimensione originale. Il valore 2 raddoppierà, mentre 0.5 ridurrà i frammenti di testo rispetto alla loro dimensione originale. Elencando più valori separati da un carattere |, lo slider userà diverse variazioni di transizione su ogni nodo di testo ciclando tra i valori forniti.'; // Scales text fragments along the X (horizontal) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks text fragments compared to their original size. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_b95364eee0d39f1ff08c9511fd007c3b'] = 'Scala i frammenti di testo lungo l\'asse Y (verticale) del vettore specificato. Usa il valore 1 per la dimensione originale. Il valore 2 raddoppierà, mentre 0.5 ridurrà i frammenti di testo rispetto alla loro dimensione originale. Elencando più valori separati da un carattere |, lo slider userà diverse variazioni di transizione su ogni nodo di testo ciclando tra i valori forniti.'; // Scales text fragments along the Y (vertical) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks text fragments compared to their original size. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_eec138a9b01bfa45053a9c2e34cc012a'] = 'Inclina i frammenti di testo lungo l\'asse X (orizzontale) del numero di gradi dato. Sono ammessi valori negativi per la direzione inversa. Elencando più valori separati da un carattere |, lo slider userà diverse variazioni di transizione su ogni nodo di testo ciclando tra i valori forniti.'; // Skews text fragments along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_0e34f559e062c73fd9f20e88a6f2dff9'] = 'Inclina i frammenti di testo lungo l\'asse Y (verticale) del numero di gradi dato. Sono ammessi valori negativi per la direzione inversa. Elencando più valori separati da un carattere |, lo slider userà diverse variazioni di transizione su ogni nodo di testo ciclando tra i valori forniti.'; // Skews text fragments along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_5160493a371ec5eaac86b380847e5df5'] = 'Spostamento in Uscita'; // Shift Out
$_MODULE['<{layerslider}prestashop>_ef90ee89ac37b9e0f7d58c40106d0489'] = 'Sposta la posizione di fine dei nodi di testo dalla loro originale sull\'asse orizzontale del numero di pixel dato. Usa valori negativi per la direzione opposta. I valori percentuali sono relativi alla larghezza di questo livello. I valori \'left\' o \'right\' posizionano i nodi di testo fuori dall\'area di staging, in modo che lascino la scena da entrambi i lati durante l\'animazione verso la loro destinazione. Elencando più valori separati da un carattere |, lo slider userà diverse variazioni di transizione su ogni nodo di testo ciclando tra i valori forniti.'; // Shifts the ending position of text nodes from their original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position text nodes out the staging area, so they leave the scene from either side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_a7dd960d399567a046b0614242132a75'] = 'Sposta la posizione di fine dei nodi di testo dalla loro originale sull\'asse verticale del numero di pixel dato. Usa valori negativi per la direzione opposta. I valori percentuali sono relativi alla larghezza di questo livello. I valori \'top\' o \'bottom\' posizionano i nodi di testo fuori dall\'area di staging, in modo che lascino la scena da entrambi i lati verticali durante l\'animazione verso la loro destinazione. Elencando più valori separati da un carattere |, lo slider userà diverse variazioni di transizione su ogni nodo di testo ciclando tra i valori forniti.'; // Shifts the ending position of text nodes from their original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'top' or 'bottom' position text nodes out the staging area, so they leave the scene from either vertical side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_d3dd82ed2edaeee8b285d11df248cc2e'] = 'Sposta la posizione di partenza del livello dalla sua originale sull\'asse orizzontale del numero di pixel dato. Usa valori negativi per la direzione opposta. I valori percentuali sono relativi alla larghezza di questo livello. I valori \'left\' o \'right\' posizionano il livello fuori dall\'area di staging, in modo che possa lasciare e rientrare in scena da entrambi i lati durante la transizione.'; // Shifts the layer starting position from its original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position the layer out the staging area, so it can leave and re-enter the scene from either side during the transition.
$_MODULE['<{layerslider}prestashop>_ad02c3d94f8b3590b135be78e2f8e69f'] = 'Sposta la posizione di partenza del livello dalla sua originale sull\'asse verticale del numero di pixel dato. Usa valori negativi per la direzione opposta. I valori percentuali sono relativi all\'altezza di questo livello. I valori \'top\' o \'bottom\' posizionano il livello fuori dall\'area di staging, in modo che possa lasciare e rientrare in scena da entrambi i lati verticali durante la transizione.'; // Shifts the layer starting position from its original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the height of this layer. The values 'top' or 'bottom' position the layer out the staging area, so it can leave and re-enter the scene from either vertical side during the transition.
$_MODULE['<{layerslider}prestashop>_7c1780aa74c2a852b5de424e51739b08'] = 'La durata della transizione in millisecondi. Un secondo equivale a 1000 millisecondi.'; // The length of the transition in milliseconds. A second is equal to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_c405823ea6eef48b12c76d719743050e'] = 'La funzione di temporizzazione dell\'animazione per manipolare il movimento del livello. Clicca sul link accanto a questo campo per aprire easings.net per esempi e maggiori informazioni'; // The timing function of the animation to manipualte the layer's movement. Click on the link next to this field to open easings.net for examples and more information
$_MODULE['<{layerslider}prestashop>_bad6a5dd8c28e6b14f8e986615e3dc98'] = 'Opacità'; // Opacity
$_MODULE['<{layerslider}prestashop>_52d096db2d41c73e647fc7b4afe9f4fb'] = 'Dissolve il livello. Puoi usare valori tra 1 e 0 per impostare il livello completamente opaco o trasparente rispettivamente. Ad esempio, il valore 0.5 renderà il livello semitrasparente.'; // Fades the layer. You can use values between 1 and 0 to set the layer fully opaque or transparent respectively. For example, the value 0.5 will make the layer semi-transparent.
$_MODULE['<{layerslider}prestashop>_e93f994f01c537c4e2f7d8528c3eb5e9'] = 'Conteggio'; // Count
$_MODULE['<{layerslider}prestashop>_dc9335e13408a714d8e29bf6e5b4af65'] = 'Il numero di volte che si ripete la transizione in loop. Il conteggio include la parte inversa delle transizioni quando si utilizza la funzione Yoyo. Usa il valore -1 per ripetere all\'infinito o zero per disabilitare il loop.'; // The number of times repeating the Loop transition. The count includes the reverse part of the transitions when you use the Yoyo feature. Use the value -1 to repeat infinitely or zero to disable looping.
$_MODULE['<{layerslider}prestashop>_0f68101772bd5397ef8eb1b632798652'] = 'Attesa'; // Wait
$_MODULE['<{layerslider}prestashop>_a2dd61cfcfc0bbdf8e5d0bacf03a4bfe'] = 'Tempo di attesa tra le ripetizioni in millisecondi. Un secondo equivale a 1000 millisecondi.'; // Waiting time between repeats in milliseconds. A second is 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_7eebb65ba3f2d0b0d5ca4135a1291800'] = 'Yoyo'; // Yoyo
$_MODULE['<{layerslider}prestashop>_d2157b3302d4ec2fb08023a69d4568fd'] = 'Abilita questa opzione per consentire la transizione inversa, in modo da poter ciclare avanti e indietro senza interruzioni.'; // Enable this option to allow reverse transition, so you can loop back and forth seamlessly.
$_MODULE['<{layerslider}prestashop>_0211cac74bd72aaae2f7886b1cbde16f'] = 'Sposta il livello orizzontalmente del numero di pixel dato. Usa valori negativi per la direzione opposta. I valori percentuali sono relativi alla larghezza di questo livello. '; // Moves the layer horizontally by the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer.
$_MODULE['<{layerslider}prestashop>_780daa5a10788add2c24feda0a7046c9'] = 'Sposta il livello verticalmente del numero di pixel dato. Usa valori negativi per la direzione opposta. I valori percentuali sono relativi alla larghezza di questo livello. '; // Moves the layer vertically by the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer.
$_MODULE['<{layerslider}prestashop>_70f03c22e8756d36e8ebebf24fc83e68'] = 'Durata<br>inversa'; // Reverse<br>duration
$_MODULE['<{layerslider}prestashop>_f611f13e9d52fe21bddfa2b3c9c6e90a'] = 'La durata della transizione inversa in millisecondi. Un secondo equivale a 1000 millisecondi.'; // The duration of the reverse transition in milliseconds. A second is equal to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_36883b3adac19e03ce6e8258a16fbd87'] = 'Easing<br>inverso'; // Reverse<br>easing
$_MODULE['<{layerslider}prestashop>_0e95be22e52ba91b2a4eac69dea794c6'] = 'La funzione di temporizzazione dell\'animazione inversa per manipolare il movimento del livello. Clicca sul link accanto a questo campo per aprire easings.net per esempi e maggiori informazioni'; // The timing function of the reverse animation to manipualte the layer's movement. Click on the link next to this field to open easings.net for examples and more information
$_MODULE['<{layerslider}prestashop>_18520e0c41ef4863b7c3d57b41e13dd2'] = 'Ruota il livello in senso orario del numero di gradi dato. Sono ammessi valori negativi per la rotazione in senso antiorario.'; // Rotates the layer clockwise by the given number of degrees. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_178d558f0ec11adc7f14494caafecfa4'] = 'Il colore di sfondo di questo livello. Puoi usare nomi di colori, valori esadecimali, RGB o RGBA così come la parola chiave \'transparent\'. Esempio: #FFF'; // The background color of this layer. You can use color names, hexadecimal, RGB or RGBA values as well as the 'transparent' keyword. Example: #FFF
$_MODULE['<{layerslider}prestashop>_7ccb130b01ecf6f307e49d85d78101ae'] = 'Il colore di questo testo. Puoi usare nomi di colori, valori esadecimali, RGB o RGBA. Esempio: #333'; // The text color of this text. You can use color names, hexadecimal, RGB or RGBA values. Example: #333
$_MODULE['<{layerslider}prestashop>_22b4e7bf3118d625243554505037c3d4'] = 'Angoli arrotondati'; // Rounded corners
$_MODULE['<{layerslider}prestashop>_8baecbc8f47d34ba6f2c94c840039b5d'] = 'Se vuoi angoli arrotondati, puoi impostare qui il loro raggio in pixel. Esempio: 5px'; // If you want rounded corners, you can set here its radius in pixels. Example: 5px
$_MODULE['<{layerslider}prestashop>_91b9f1c422bb9c80c97c1409c449b01a'] = 'Cambia la prospettiva dei livelli nello spazio 3D.'; // Changes the perspective of layers in the 3D space.
$_MODULE['<{layerslider}prestashop>_7b57923badae7705a941c2bb5fdbc259'] = 'Sempre in primo piano'; // Always on top
$_MODULE['<{layerslider}prestashop>_97309a236d6310d21531928e0f237909'] = 'Mostra questo livello sopra ogni altro livello al passaggio del mouse.'; // Show this layer above every other layer while hovering.
$_MODULE['<{layerslider}prestashop>_b437c451aa3282f75304078beaccd7f2'] = 'Livello Parallasse'; // Parallax Level
$_MODULE['<{layerslider}prestashop>_6d88cda2a17e8c8ba371534044e4dcac'] = 'Imposta l\'intensità dell\'effetto parallasse. Usa valori negativi per spostare i livelli nella direzione opposta.'; // Set the intensity of the parallax effect. Use negative values to shift layers in the opposite direction.
$_MODULE['<{layerslider}prestashop>_e32aeb1f97bbc4b3734bceba06e62189'] = 'Scegli se vuoi livelli parallasse 2D o 3D.'; // Choose if you want 2D or 3D parallax layers.
$_MODULE['<{layerslider}prestashop>_db7e7d3165d15f05c446c312cd7ce748'] = 'Eredita dalle Opzioni Slide'; // Inherit from Slide Options
$_MODULE['<{layerslider}prestashop>_65c19dcd436dba37e3f61abaa74fcb0a'] = 'Puoi attivare l\'effetto parallasse scorrendo la pagina, oppure muovendo il cursore del mouse / inclinando il tuo dispositivo mobile.'; // You can trigger the parallax effect by either scrolling the page, or by moving your mouse cursor / tilting your mobile device.
$_MODULE['<{layerslider}prestashop>_df4937d57d5546a1b7cad8aa01382a30'] = 'Scegli su quali assi i livelli parallasse devono muoversi.'; // Choose on which axes parallax layers should move.
$_MODULE['<{layerslider}prestashop>_130c5b3473c57faa76e2a1c54e26f88e'] = 'Entrambi'; // Both
$_MODULE['<{layerslider}prestashop>_f8669b1c29bb1d386ed994a5fa3b2383'] = 'Durata Movimento'; // Move Duration
$_MODULE['<{layerslider}prestashop>_902394e5c2f298dc004991c64ea639e0'] = 'Controlla la velocità di animazione dei livelli quando muovi il cursore del mouse o inclini il tuo dispositivo mobile.'; // Controls the speed of animating layers when you move your mouse cursor or tilt your mobile device.
$_MODULE['<{layerslider}prestashop>_e6c62193f078181acd6cc60c21353d08'] = 'Durata Uscita'; // Leave Duration
$_MODULE['<{layerslider}prestashop>_387b79d99e6882187a0e3530f37a2f76'] = 'Controlla la rapidità con cui i livelli parallasse tornano alla loro posizione originale quando sposti il cursore del mouse fuori dallo slider. Questo valore è in millisecondi. Un secondo equivale a 1000 millisecondi.'; // Controls how quickly parallax layers revert to their original position when you move your mouse cursor outside of the slider. This value is in milliseconds. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_64a0612acd329567a634da43b59883cf'] = 'Aumenta o diminuisci la quantità di rotazione del livello nello spazio 3D quando sposti il cursore del mouse o inclini un dispositivo mobile.'; // Increase or decrease the amount of layer rotation in the 3D space when moving your mouse cursor or tilting on a mobile device.
$_MODULE['<{layerslider}prestashop>_fb86197f4f68b1e2d86783659e7585a3'] = 'Aumenta o diminuisci la quantità di movimento del livello quando sposti il cursore del mouse o inclini un dispositivo mobile.'; // Increase or decrease the amount of layer movement when moving your mouse cursor or tilting on a mobile device.
$_MODULE['<{layerslider}prestashop>_7b62b4d0a7de4d976159fb96a6fa6411'] = 'Livello statico'; // Static layer
$_MODULE['<{layerslider}prestashop>_9ae2250c53514362ad6490c3431e5464'] = 'Puoi mantenere questo livello sopra lo slider attraverso più slide. Seleziona semplicemente la slide su cui questo livello dovrebbe animarsi in uscita. In alternativa, puoi rendere questo livello globale su tutte le slide dopo la sua transizione in entrata.'; // You can keep this layer on top of the slider across multiple slides. Just select the slide on which this layer should animate out. Alternatively, you can make this layer global on all slides after it transitioned in.
$_MODULE['<{layerslider}prestashop>_9c2690b8a4048048e2c037e4a03339b0'] = 'Disabilitato (predefinito)'; // Disabled (default)
$_MODULE['<{layerslider}prestashop>_1d7e5793a0150b3c05de1922cc8c16f5'] = 'Abilitato (non animare mai in uscita)'; // Enabled (never animate out)
$_MODULE['<{layerslider}prestashop>_2a36e79a98871dc76bf33a51af7e3715'] = 'Keyframe Riproduzione con Scorrimento'; // Play By Scroll Keyframe
$_MODULE['<{layerslider}prestashop>_8e898860158d07998968bfd485788069'] = 'Uno slider con Riproduzione con Scorrimento si fermerà quando questo livello avrà terminato la sua transizione di apertura.'; // A Play by Scroll slider will pause when this layer finished its opening transition.
$_MODULE['<{layerslider}prestashop>_627b4c0e8a9b46747497d4bae491a6c2'] = 'Se vuoi collegare il tuo livello, digita qui l\'URL. Puoi usare un cancelletto seguito da un numero per collegare questo livello a un\'altra slide. Esempio: #3 - questo passerà alla terza slide.'; // If you want to link your layer, type here the URL. You can use a hash mark followed by a number to link this layer to another slide. Example: #3 - this will switch to the third slide.
$_MODULE['<{layerslider}prestashop>_a33a3e8542755c06996a81a78878b66b'] = 'Target URL'; // URL target
$_MODULE['<{layerslider}prestashop>_ba333933886b07c9384523873559a3fd'] = 'Attributi Personalizzati'; // Custom Attributes
$_MODULE['<{layerslider}prestashop>_a016d8e10948cfc95215918d4372d8f9'] = 'La tua lista di attributi personalizzati. Usa questa funzione se le tue esigenze non sono coperte dagli attributi comuni sopra o se vuoi sovrascriverli. Puoi usare data-* così come nomi di attributi regolari. Sono ammessi anche attributi vuoti (senza valore). Ad esempio, per creare una galleria FancyBox, potresti inserire "data-fancybox-group" e "gallery1" rispettivamente per il nome e il valore dell\'attributo.'; // Your list of custom attributes. Use this feature if your needs are not covered by the common attributes above or you want to override them. You can use data-* as well as regular attribute names. Empty attributes (without value) are also allowed. For example, to make a FancyBox gallery, you may enter "data-fancybox-group" and "gallery1" for the attribute name and value, respectively.
$_MODULE['<{layerslider}prestashop>_edac8da7d60b7624d4b131bc47a5eb3b'] = 'Puoi impostare la larghezza del tuo livello. Puoi usare pixel, percentuale o il valore predefinito \'auto\'. Esempi: 100px, 50% o auto.'; // You can set the width of your layer. You can use pixels, percentage, or the default value 'auto'. Examples: 100px, 50% or auto.
$_MODULE['<{layerslider}prestashop>_c6272de402f4e075758f7d27f108d6c1'] = 'Puoi impostare l\'altezza del tuo livello. Puoi usare pixel, percentuale o il valore predefinito \'auto\'. Esempi: 100px, 50% o auto'; // You can set the height of your layer. You can use pixels, percentage, or the default value 'auto'. Examples: 100px, 50% or auto
$_MODULE['<{layerslider}prestashop>_a4ffdcf0dc1f31b9acaf295d75b51d00'] = 'Sopra'; // Top
$_MODULE['<{layerslider}prestashop>_4ce53ede45d38aa6228b7a2e4a9a2d6f'] = 'La posizione del livello dalla parte superiore della slide. Puoi usare pixel e percentuale. Esempi: 100px o 50%. Puoi spostare i tuoi livelli nell\'anteprima sopra con un drag n\' drop, o impostare i valori esatti qui.'; // The layer position from the top of the slide. You can use pixels and percentage. Examples: 100px or 50%. You can move your layers in the preview above with a drag n' drop, or set the exact values here.
$_MODULE['<{layerslider}prestashop>_945d5e233cf7d6240f6b783b36a374ff'] = 'Sinistra'; // Left
$_MODULE['<{layerslider}prestashop>_38ab4523d162374efdee06dcaa89d7dd'] = 'La posizione del livello dal lato sinistro della slide. Puoi usare pixel e percentuale. Esempi: 100px o 50%. Puoi spostare i tuoi livelli nell\'anteprima sopra con un drag n\' drop, o impostare i valori esatti qui.'; // The layer position from the left side of the slide. You can use pixels and percentage. Examples: 100px or 50%. You can move your layers in the preview above with a drag n' drop, or set the exact values here.
$_MODULE['<{layerslider}prestashop>_9bef4210a675b3352481eaba774135e2'] = 'Padding sulla parte superiore del livello. Esempio: 10px'; // Padding on the top of the layer. Example: 10px
