$_MODULE['<{layerslider}prestashop>_f8e3211bbd5d1c9e4bbe92fb5006478e'] = 'Stile carattere'; // Font style
$_MODULE['<{layerslider}prestashop>_935d167268be2e114d55069d55e1a408'] = 'Oblique è una versione corsiva generata automaticamente del carattere scelto e può forzare l\'inclinazione anche se non è disponibile una variante di carattere corsivo. Tuttavia, dovresti usare l\'opzione corsiva regolare ogni volta che è possibile. Controlla di caricare le varianti di carattere corsivo quando usi Google Fonts.'; // Oblique is an auto-generated italic version of your chosen font and can force slating even if there is no italic font variant available. However, you should use the regular italic option whenever is possible. Please double check to load italic font variants when using Google Fonts.
$_MODULE['<{layerslider}prestashop>_1d874710ccdcd46b95397049d2e7500c'] = 'Corsivo'; // Italic
$_MODULE['<{layerslider}prestashop>_aa2870bb0730c19998358f5cdbc0dc1b'] = 'Obliquo (inclinazione forzata)'; // Oblique (Forced slant)
$_MODULE['<{layerslider}prestashop>_1fc25820929d0d57c6556736502549e0'] = 'Decorazione testo'; // Text decoration
$_MODULE['<{layerslider}prestashop>_852721aa5fc738dfedff2945d71da439'] = 'Sottolineato'; // Underline
$_MODULE['<{layerslider}prestashop>_a7d7d34d28ecacfa945c78f1ae7ec675'] = 'Sopralineato'; // Overline
$_MODULE['<{layerslider}prestashop>_0523cf1b90dbb38842309634f8b03dc2'] = 'Barrato'; // Line through
$_MODULE['<{layerslider}prestashop>_78d69c3e5d462a8f6f17fb2467e65d6b'] = 'Spaziatura lettere'; // Letter spacing
$_MODULE['<{layerslider}prestashop>_6d40b0cbf0593b752ece63f7a9928eef'] = 'Controlla la quantità di spazio tra ogni carattere. Utile per cambiare la densità delle lettere in una riga o in un blocco di testo. Si possono usare valori negativi e decimali.'; // Controls the amount of space between each character. Useful the change letter density in a line or block of text. Negative values and decimals can be used.
$_MODULE['<{layerslider}prestashop>_c22b28c5c38d219b521e476691bd7158'] = 'Allineamento testo'; // Text align
$_MODULE['<{layerslider}prestashop>_6c982f951a9fa0736c853e9353ff1553'] = 'Iniziale (predefinito lingua)'; // Initial (Language default)
$_MODULE['<{layerslider}prestashop>_4f1f6016fc9f3f2353c0cc7c67b292bd'] = 'Centro'; // Center
$_MODULE['<{layerslider}prestashop>_4b425d212a2e7b36c38703bfdcd57823'] = 'Giustificato'; // Justify
$_MODULE['<{layerslider}prestashop>_a8bc50a5bb0ee94aef28600eeccfaa60'] = 'Dim. carattere min.'; // Min. font size
$_MODULE['<{layerslider}prestashop>_cd7ab6145e3bf89a25e376abd17ab01e'] = 'La dimensione minima del carattere in uno slider responsive. Questa opzione ti permette di evitare che i tuoi livelli di testo diventino troppo piccoli su schermi più piccoli.'; // The minimum font size in a responsive slider. This option allows you to prevent your texts layers becoming too small on smaller screens.
$_MODULE['<{layerslider}prestashop>_e0bc0f8bfc07dfaa60de8a19a075ecaf'] = 'Dim. carattere min. mobile'; // Min. mobile font size
$_MODULE['<{layerslider}prestashop>_56cac8df2a819eb309f656bec767e641'] = 'La dimensione minima del carattere in uno slider responsive su dispositivi mobili. Questa opzione ti permette di evitare che i tuoi livelli di testo diventino troppo piccoli su schermi più piccoli.'; // The minimum font size in a responsive slider on mobile devices. This option allows you to prevent your texts layers becoming too small on smaller screens.
$_MODULE['<{layerslider}prestashop>_ee0b6a872572cc985f1d5d20a5901ffb'] = 'Se vuoi angoli arrotondati, puoi impostare il loro raggio qui. Esempio: 5px'; // If you want rounded corners, you can set its radius here. Example: 5px
$_MODULE['<{layerslider}prestashop>_856ba67470300f8246b140de9a27555d'] = 'Stili personalizzati'; // Custom styles
$_MODULE['<{layerslider}prestashop>_7e045337d227fc13f0b7efdadf341169'] = 'Se vuoi impostare opzioni di stile diverse da quelle sopra, puoi usare qui qualsiasi codice CSS. Assicurati di scrivere un markup valido.'; // If you want to set style settings other than above, you can use here any CSS codes. Please make sure to write valid markup.
$_MODULE['<{layerslider}prestashop>_3dbe275d40b3a2b680bdfa25242cc8fe'] = 'L\'angolo di rotazione verso cui questo livello si anima entrando nel canvas dello slider. Sono ammessi valori negativi per la rotazione in senso antiorario.'; // The rotation angle where this layer animates toward when entering into the slider canvas. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_fe75b60943091f007ae820a3188868a2'] = 'L\'angolo di rotazione sull\'asse orizzontale verso cui si anima entrando nel canvas dello slider. Sono ammessi valori negativi per la direzione inversa.'; // The rotation angle on the horizontal axis where this animates toward when entering into the slider canvas. Negative values are allowed for reversed direction.
$_MODULE['<{layerslider}prestashop>_0c6a5ad5f832c1f79c4b4d62fee16e26'] = 'L\'angolo di rotazione sull\'asse verticale verso cui questo livello si anima entrando nel canvas dello slider. Sono ammessi valori negativi per la direzione inversa.'; // The rotation angle on the vertical axis where this layer animates toward when entering into the slider canvas. Negative values are allowed for reversed direction.
$_MODULE['<{layerslider}prestashop>_6af83f149c018cdec1dba351c619b7ca'] = 'La scala orizzontale del livello verso cui questo livello si anima entrando nel canvas dello slider.'; // The layer horizontal scale where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_28d8b2ec189dc2eb778a851265cf4f26'] = 'La scala verticale del livello verso cui questo livello si anima entrando nel canvas dello slider.'; // The layer vertical scale where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_63d48e08093f6964b3cdc6d33740663e'] = 'L\'angolo di inclinazione orizzontale del livello verso cui questo livello si anima entrando nel canvas dello slider.'; // The layer horizontal skewing angle where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_e4b23d4080824b973029720a307cbae6'] = 'L\'angolo di inclinazione verticale del livello verso cui questo livello si anima entrando nel canvas dello slider.'; // The layer vertical skewing angle where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_45f908bb74a7835d23630c7d51031fed'] = 'Calcola posizioni da'; // Calculate positions from
$_MODULE['<{layerslider}prestashop>_639b76980c25ea95700d2c2e96833964'] = 'Imposta l\'origine della posizione del livello da cui vengono calcolati i valori top e left. Il predefinito è l\'angolo in alto a sinistra del canvas dello slider. In uno slider a larghezza e dimensione piena, il tuo contenuto è centrato in base alla dimensione dello schermo per ottenere la migliore vestibilità possibile. Selezionando l\'opzione "lati dello schermo" in questi scenari, puoi permettere ai livelli di uscire dall\'area interna centrata e aderire ai lati dello schermo.'; // Sets the layer position origin from which top and left values are calculated. The default is the upper left corner of the slider canvas. In a full width and full size slider, your content is centered based on the screen size to achieve the best possible fit. By selecting the "sides of the screen" option in those scenarios, you can allow layers to escape the centered inner area and stick to the sides of the screen.
$_MODULE['<{layerslider}prestashop>_b16710c8d62abca1ccda544c63bea7e8'] = 'lati dello slider'; // sides of the slider
$_MODULE['<{layerslider}prestashop>_ab761fc53dc83dca5a36b9a25bf548bf'] = 'lati dello schermo'; // sides of the screen
$_MODULE['<{layerslider}prestashop>_51400b417ad07f539ecfd9469027a5b6'] = 'Ordine di impilamento'; // Stacking order
$_MODULE['<{layerslider}prestashop>_4c26a68fa7463987e86f61733caf8491'] = 'Questa opzione controlla l\'ordine di impilamento verticale dei livelli che si sovrappongono. In CSS, è comunemente chiamato z-index. Gli elementi con un valore più alto sono impilati davanti agli elementi con un valore più basso, coprendoli efficacemente. Per impostazione predefinita, questo valore viene calcolato automaticamente in base all\'ordine dei tuoi livelli, quindi un semplice riordino può risolvere problemi di sovrapposizione. Usa questa opzione solo se vuoi impostare manualmente il tuo valore in casi speciali come l\'uso di livelli statici.<br><br>Su ogni slide, l\'ordine di impilamento inizia a contare da 100. Fornire un numero inferiore a 100 metterà il livello dietro ogni altro livello su tutte le slide. Specificare un numero molto più grande, ad esempio 500, farà sì che il livello sia sopra a tutto il resto.'; // This option controls the vertical stacking order of layers that overlap. In CSS, it's commonly called as z-index. Elements with a higher value are stacked in front of elements with a lower one, effectively covering them. By default, this value is calculated automatically based on the order of your layers, thus simply re-ordering them can fix overlap issues. Use this option only if you want to set your own value manually in special cases like using static layers.<br><br>On each slide, the stacking order starts counting from 100. Providing a number less than 100 will put the layer behind every other layer on all slides. Specifying a much greater number, for example 500, will make the layer to be on top of everything else.
$_MODULE['<{layerslider}prestashop>_0c301043ef92f5854d711e54f96a86c5'] = 'Modalità di fusione'; // Blend mode
$_MODULE['<{layerslider}prestashop>_df5c4d0c2cd9156afa20fa59c572acde'] = 'Scegli come i livelli e lo sfondo della slide dovrebbero fondersi tra loro. Le modalità di fusione sono un modo semplice per aggiungere effetti accattivanti ed è una delle funzionalità più utilizzate nel design grafico e di stampa.'; // Choose how layers and the slide background should blend into each other. Blend modes are an easy way to add eye-catching effects and is one of the most frequently used features in graphic and print design.
$_MODULE['<{layerslider}prestashop>_b718adec73e04ce3ec720dd11a06a308'] = 'ID'; // ID
$_MODULE['<{layerslider}prestashop>_ca79528715d6c07cb429e8189105cbb4'] = 'Puoi applicare un attributo ID all\'elemento HTML di questo livello per lavorarci nel tuo codice CSS o Javascript personalizzato.'; // You can apply an ID attribute on the HTML element of this layer to work with it in your custom CSS or Javascript code.
$_MODULE['<{layerslider}prestashop>_e9878b4854d29907146149f695cb1cfb'] = 'Classi'; // Classes
$_MODULE['<{layerslider}prestashop>_c666f7b19a598af3cadb8c9cb07c4bcd'] = 'Puoi applicare classi all\'elemento HTML di questo livello per lavorarci nel tuo codice CSS o Javascript personalizzato.'; // You can apply classes on the HTML element of this layer to work with it in your custom CSS or Javascript code.
$_MODULE['<{layerslider}prestashop>_3ace045d5becea8953aabde365c5c8d8'] = 'Puoi aggiungere un titolo a questo livello che verrà visualizzato come tooltip se qualcuno tiene il cursore del mouse sopra il livello.'; // You can add a title to this layer which will display as a tooltip if someone holds his mouse cursor over the layer.
$_MODULE['<{layerslider}prestashop>_f2364c335fe8ae15c8d64b2744db0f40'] = 'Assegna un nome o descrivi il tuo livello immagine, in modo che i motori di ricerca e i software di lettura vocale possano identificarlo correttamente.'; // Name or describe your image layer, so search engines and VoiceOver softwares can properly identify it.
$_MODULE['<{layerslider}prestashop>_eba991d56b1be0b940d722211bab87bc'] = 'Rel'; // Rel
$_MODULE['<{layerslider}prestashop>_b987cf5b1aa6af2a92b97f69d65c29df'] = 'I plugin e i motori di ricerca possono usare questo attributo per ottenere maggiori informazioni sul ruolo e il comportamento di un link.'; // Plugins and search engines may use this attribute to get more information about the role and behavior of a link.
$_MODULE['<{layerslider}prestashop>_5d083603a18046659c2b4b23af7948cc'] = 'Opzione avanzata'; // Advanced option
$_MODULE['<{layerslider}prestashop>_31fde7b05ac8952dacf4af8a704074ec'] = 'Anteprima'; // Preview
$_MODULE['<{layerslider}prestashop>_a67f2c9d056f29b94521c17b838b9756'] = 'Tessere'; // Tiles
$_MODULE['<{layerslider}prestashop>_530f488f7a9800411efc6926ab189708'] = 'Righe'; // Rows
$_MODULE['<{layerslider}prestashop>_35b93b52adc0893d6f4b32752660535f'] = '<i>numero</i> o <i>min,max</i> Se specifichi un valore maggiore di 1, Creative Slider taglierà la tua slide in tessere. Puoi specificare qui quante righe deve avere la tua transizione. Se specifichi due numeri separati da una virgola, Creative Slider lo userà come un intervallo e sceglierà un numero casuale tra i tuoi valori.'; // <i>number</i> or <i>min,max</i> If you specify a value greater than 1, Creative Slider will cut your slide into tiles. You can specify here how many rows of your transition should have. If you specify two numbers separated with a comma, Creative Slider will use that as a range and pick a random number between your values.
$_MODULE['<{layerslider}prestashop>_d27561f45c58f407b3fe76b63b1ec28a'] = 'Colonne'; // Cols
$_MODULE['<{layerslider}prestashop>_a122bf49cbf8c9cf02971a495e81ed16'] = '<i>numero</i> o <i>min,max</i> Se specifichi un valore maggiore di 1, Creative Slider taglierà la tua slide in tessere. Puoi specificare qui quante colonne deve avere la tua transizione. Se specifichi due numeri separati da una virgola, Creative Slider lo userà come un intervallo e sceglierà un numero casuale tra i tuoi valori.'; // <i>number</i> or <i>min,max</i> If you specify a value greater than 1, Creative Slider will cut your slide into tiles. You can specify here how many columns of your transition should have. If you specify two numbers separated with a comma, Creative Slider will use that as a range and pick a random number between your values.
$_MODULE['<{layerslider}prestashop>_8f497c1a3d15af9e0c215019f26b887d'] = 'Ritardo'; // Delay
$_MODULE['<{layerslider}prestashop>_d4f0208d1a34d7a381fc8abec990105b'] = 'Puoi applicare un ritardo tra le tessere e posticipare la loro animazione l\'una rispetto all\'altra.'; // You can apply a delay between the tiles and postpone their animation relative to each other.
$_MODULE['<{layerslider}prestashop>_3ff39d3acb327553070a64ef0cb321d5'] = 'Sequenza'; // Sequence
$_MODULE['<{layerslider}prestashop>_434cd8b268e79b39af562cc6329d56fb'] = 'Puoi controllare l\'ordine di animazione delle tessere qui.'; // You can control the animation order of the tiles here.
$_MODULE['<{layerslider}prestashop>_67d2f6740a8eaebf4d5c6f79be8da481'] = 'Avanti'; // Forward
$_MODULE['<{layerslider}prestashop>_67f115c1fddc4ce1aeb1c754001585bc'] = 'Indietro'; // Reverse
$_MODULE['<{layerslider}prestashop>_13db785ec723ba5b44f1a1311edc9332'] = 'Col-avanti'; // Col-forward
$_MODULE['<{layerslider}prestashop>_3898dd1cf4144fda9dfac68e6c3b7c41'] = 'Col-indietro'; // Col-reverse
$_MODULE['<{layerslider}prestashop>_afedf9afee367f51f98d7cf030c976a6'] = 'Transizione'; // Transition
$_MODULE['<{layerslider}prestashop>_1f3b894b65d30b6d1f137f4b4dad7823'] = 'La durata dell\'animazione. Questo valore è in millisecondi, quindi il valore 1000 significa 1 secondo.'; // The duration of the animation. This value is in millisecs, so the value 1000 measn 1 second.
$_MODULE['<{layerslider}prestashop>_639a36a8fd5673fccfa75e572ca859f7'] = 'Il tipo di animazione, o slide, o dissolvenza o entrambi (misto).'; // The type of the animation, either slide, fade or both (mixed).
$_MODULE['<{layerslider}prestashop>_6160a53ece50ce6d4f5ef4452549835e'] = 'Slide'; // Slide
$_MODULE['<{layerslider}prestashop>_699b4f79215d191584653efebf156e52'] = 'Misto'; // Mixed
$_MODULE['<{layerslider}prestashop>_02674a4ef33e11c879283629996c8ff8'] = 'Direzione'; // Direction
$_MODULE['<{layerslider}prestashop>_b8086e22ac8d37e35a011973d392361a'] = 'La direzione dell\'animazione di slide o mista se hai scelto questo tipo nelle impostazioni precedenti.'; // The direction of the slide or mixed animation if you've chosen this type in the previous settings.
$_MODULE['<{layerslider}prestashop>_a4d0d101d6a34bf80ffeee601c3ff84a'] = 'Alto sinistra'; // Top left
$_MODULE['<{layerslider}prestashop>_d3708546a929dfcf66eaeaba794486eb'] = 'Alto destra'; // Top right
$_MODULE['<{layerslider}prestashop>_b67554192c50f4f6a4c1bd4797f6c3f8'] = 'Basso sinistra'; // Bottom left
$_MODULE['<{layerslider}prestashop>_5968e3c37145f57587afcba727d2b120'] = 'Basso destra'; // Bottom right
$_MODULE['<{layerslider}prestashop>_eb7933783169e45d0670c08c9537270e'] = 'La rotazione iniziale delle singole tessere che verranno animate al valore predefinito (0deg) attorno all\'asse X. Puoi usare valori negativi.'; // The initial rotation of the individual tiles which will be animated to the default (0deg) value around the X axis. You can use negatuve values.
$_MODULE['<{layerslider}prestashop>_e7e6c5827f1c629a2f50e13ddd7bfbdf'] = 'La rotazione iniziale delle singole tessere che verranno animate al valore predefinito (0deg) attorno all\'asse Y. Puoi usare valori negativi.'; // The initial rotation of the individual tiles which will be animated to the default (0deg) value around the Y axis. You can use negatuve values.
$_MODULE['<{layerslider}prestashop>_9ebd255ed8317380a778935c957e7410'] = 'RotazioneZ'; // RotateZ
