$_MODULE['<{layerslider}prestashop>_aea7745e8f5d7a59d9d8d8d4f3ff31f3'] = 'La scala iniziale delle singole tessere che verranno animate al valore predefinito (1.0).'; // The initial scale of the individual tiles which will be animated to the default (1.0) value.
