$_MODULE['<{layerslider}prestashop>_dae53216ad3909742ad508599f4f524c'] = 'Gli effetti speciali sono come le transizioni di slide regolari e funzionano allo stesso modo. Puoi impostarli su ogni slide individualmente. Mescolarli con altre transizioni su altre slide è perfettamente possibile. Puoi anche applicarli a tutte le tue slide contemporaneamente premendo il pulsante "Applica ad altri" sopra. In caso di effetti speciali 3D, la selezione di transizioni 2D aggiuntive può garantire la compatibilità con i browser più vecchi.'; // Special effects are like regular slide transitions and they work in the same way. You can set them on each slide individually. Mixing them with other transitions on other slides is perfectly fine. You can also apply them on all of your slides at once by pressing the "Apply to others" button above. In case of 3D special effects, selecting additional 2D transitions can ensure backward compatibility for older browsers.
$_MODULE['<{layerslider}prestashop>_b8855caaf641a9f8cd794b263fd3187f'] = 'Transizione Origami'; // Origami transition
$_MODULE['<{layerslider}prestashop>_120a5b58df4cf329020874fee6e1a01c'] = 'Condividi le tue splendide foto con il mondo o i tuoi cari in un modo davvero stimolante e crea slider con effetti mozzafiato con Origami.'; // Share your gorgeous photos with the world or your loved ones in a truly inspirational way and create sliders with stunning effects with Origami.
$_MODULE['<{layerslider}prestashop>_2b0cda1ac8369a2372e2de48907dabc4'] = 'Origami è una forma di transizione 3D e funziona allo stesso modo delle transizioni di slide regolari. Oltre a Internet Explorer, Origami funziona in tutti i browser moderni (incluso Edge).'; // Origami is a form of 3D transition and it works in the same way as regular slide transitions do. Besides Internet Explorer, Origami works in all the modern browsers (including Edge).
