$_MODULE['<{layerslider}prestashop>_d69de1175ad3d34048bfd72f8c2728ea'] = 'Cerchi il contenuto demo importabile? Controlla il %sNegozio dei Modelli%s.'; // Looking for the importable demo content? Check out the %sTemplate Store%s.
$_MODULE['<{layerslider}prestashop>_cc0da7a91d632e541ca11db8e8e77c18'] = 'Avviso: Per importare da versioni obsolete (pre-v3.0.0), è necessario creare un nuovo file e incollare il codice di esportazione al suo interno. Il file deve avere un\'estensione .json, quindi potrai caricarlo.'; // Notice: In order to import from outdated versions (pre-v3.0.0), you need to create a new file and paste the export code into it. The file needs to have a .json extension, then you will be able to upload it.
$_MODULE['<{layerslider}prestashop>_d1673e2c8908f8939c5d0ba949ebc80b'] = 'Importa Slider'; // Import Sliders
$_MODULE['<{layerslider}prestashop>_00a38f6db60b94e13225141261806f19'] = 'Non ci sono ancora revisioni disponibili per lo slider selezionato. Le revisioni verranno aggiunte nel tempo man mano che apporti nuove modifiche ai tuoi slider. Controlla %sPreferenze Revisioni%s e assicurati che le Revisioni siano abilitate.'; // There are no revisions available for the selected slider yet. Revisions will be added over time when you make new changes to your sliders. Check %sRevisions Preferences%s and make sure that Revisions is enabled.
