$_MODULE['<{layerslider}prestashop>_6240283f8cafe0d117e4429ce194a4b0'] = 'Aggiungi nuova slide'; // Add new slide
$_MODULE['<{layerslider}prestashop>_d3d7a8120d679586210a531b07f536c1'] = 'Si prega di leggere la nostra %sdocumentazione online%s prima di iniziare a usare l\'API. Creative Slider 6 ha introdotto un modello API completamente nuovo con eventi e metodi diversi.'; // Please read our %sonline documentation%s before start using the API. Creative Slider 6 introduced an entirely new API model with different events and methods.
$_MODULE['<{layerslider}prestashop>_2a5043ba5b444cfd9b6dd0f8649e0f68'] = 'Si attiva prima dell\'analisi delle impostazioni utente e del rendering dell\'interfaccia utente.'; // Fires before parsing user settings and rendering the UI.
$_MODULE['<{layerslider}prestashop>_3f548b1fd22737b7d5dde9f995a6feaf'] = 'Si attiva quando lo slider è completamente inizializzato e i suoi nodi DOM diventano accessibili.'; // Fires when the slider is fully initialized and its DOM nodes become accessible.
$_MODULE['<{layerslider}prestashop>_92cd10cd1c4cf877f896d78fa42bfd57'] = 'Eventi di Ridimensionamento'; // Resize Events
$_MODULE['<{layerslider}prestashop>_65fffb715673a009323e236ae205b11e'] = 'Si attiva prima che lo slider renda gli eventi di ridimensionamento.'; // Fires before the slider renders resize events.
$_MODULE['<{layerslider}prestashop>_bf8432ff4d101ba87a4a8f89e07bbd2d'] = 'Si attiva dopo che lo slider ha reso gli eventi di ridimensionamento.'; // Fires after the slider has rendered resize events.
$_MODULE['<{layerslider}prestashop>_18ccc4029c3d11945bce208d25c18171'] = 'Eventi Slideshow'; // Slideshow Events
$_MODULE['<{layerslider}prestashop>_064c7b60a2915897038de37bec1f396a'] = 'Si attiva a ogni cambio di stato dello slideshow, che potrebbe non influenzare lo stato di riproduzione.'; // Fires upon every slideshow state change, which may not influence the playing status.
$_MODULE['<{layerslider}prestashop>_3d1eb7129e598455d7df1eec136e58db'] = 'Si attiva quando lo slideshow va in pausa dallo stato di riproduzione.'; // Fires when the slideshow pauses from playing status.
$_MODULE['<{layerslider}prestashop>_a5719146f8c59bff10bc74f52661b4e9'] = 'Si attiva quando lo slideshow riprende dallo stato di pausa.'; // Fires when the slideshow resumes from paused status.
$_MODULE['<{layerslider}prestashop>_670d3f900b4a82acf6caa8d21c393a61'] = 'Eventi Cambio Slide'; // Slide Change Events
$_MODULE['<{layerslider}prestashop>_55d74f43e3bee7da6ec429497b8f9f61'] = 'Segnala quando lo slider vuole cambiare slide, ed è la tua ultima possibilità di deviarlo o intervenire in qualsiasi modo.'; // Signals when the slider wants to change slides, and is your last chance to divert it or intervene in any way.
$_MODULE['<{layerslider}prestashop>_9a1790248220443e91be20ddd063d74c'] = 'Si attiva quando lo slider ha iniziato un cambio di slide.'; // Fires when the slider has started a slide change.
$_MODULE['<{layerslider}prestashop>_630be5a55bfbc7aeffc8df49fe43226c'] = 'Si attiva prima di completare un cambio di slide.'; // Fires before completing a slide change.
$_MODULE['<{layerslider}prestashop>_98ab2b3d5778b0e3d9f276466daa36ff'] = 'Si attiva dopo che un cambio di slide è stato completato e gli indici delle slide sono stati aggiornati. '; // Fires after a slide change has completed and the slide indexes have been updated.
$_MODULE['<{layerslider}prestashop>_f0805986c59944a85bdb479c192ef78f'] = 'Eventi Timeline Slide'; // Slide Timeline Events
$_MODULE['<{layerslider}prestashop>_b6d81103a4a457163b98e449ec06ab92'] = 'Si attiva quando la timeline dell\'animazione della slide corrente (es. i tuoi livelli) diventa accessibile per l\'interfacciamento.'; // Fires when the current slide's animation timeline (e.g. your layers) becomes accessible for interfacing.
$_MODULE['<{layerslider}prestashop>_4d266351abd32da9f2cb16fc3a0041c1'] = 'Si attiva rapidamente (ad ogni frame) per tutta la durata della slide durante la riproduzione, inclusa la riproduzione inversa.'; // Fires rapidly (at each frame) throughout the entire slide while playing, including reverse playback.
$_MODULE['<{layerslider}prestashop>_0b53e3b22c9729a524ec0b34e94df0b3'] = 'Si attiva quando la timeline dell\'animazione della slide corrente (es. i tuoi livelli) ha iniziato a riprodursi.'; // Fires when the current slide's animation timeline (e.g. your layers) has started playing.
